style.css.content:
/* Global Styles */
body {
    font-family: 'Arial', sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f4f4f4;
    color: #333;
}

.container {
    width: 80%;
    margin: auto;
    overflow: hidden;
}

/* Header Styles */
header {
    background: #503011;
    color: white;
    padding-top: 30px;
    min-height: 70px;
    border-bottom: #f7c08a 3px solid;
}

header a {
    color: white;
    text-decoration: none;
    text-transform: uppercase;
    font-size: 16px;
}

header ul {
    margin: 0;
    padding: 0;
}

header li {
    float: left;
    display: inline;
    padding: 0 20px 0 20px;
}

header #branding {
    float: left;
}

header #branding h1 {
    margin: 0;
}

header nav {
    float: right;
    margin-top: 10px;
}

header .highlight, header .current a {
    color: #f7c08a;
    font-weight: bold;
}

header a:hover {
    color: #cccccc;
    font-weight: bold;
}

/* Showcase */
#showcase {
    min-height: 400px;
    background:url('img/showcase.jpg') no-repeat;
    background-position: center;
    background-size:cover;
    text-align: center;
    color:#fff;
}

#showcase h1 {
    margin-top: 100px;
    font-size:55px;
    margin-bottom:10px;
}

#showcase p {
    font-size: 20px;
}

/* Newsletter */
#newsletter {
    padding:15px;
    color:#fff;
    background:#35424a
}

#newsletter h1 {
    float:left;
}

#newsletter form {
    float:right;
    margin-top:15px;
}

#newsletter input[type="email"]{
    padding:4px;
    height:25px;
    width:250px;
}

/* Boxes */
#boxes {
    margin-top:20px;
}

#boxes .box {
    float:left;
    text-align: center;
    width:30%;
    padding:10px;
}

#boxes .box img {
    width:90px;
}

/* Sidebar */
aside#sidebar {
    float:right;
    width:30%;
    margin-top:10px;
    padding:10px;
}

/* Article */
article#main-col {
    float:left;
    width:65%;
}

/* Services */
ul#services li {
    list-style: none;
    padding:20px;
    border: #cccccc solid 1px;
    margin-bottom:5px;
    background:#e6e6e6;
}

/* Footer */
footer {
    padding:20px;
    margin-top:20px;
    color:#fff;
    background-color:#503011;
    text-align: center;
}

/* Media Queries */
@media(max-width: 768px) {
    header #branding, header nav {
        float: none;
        text-align: center;
    }

    header nav li {
        float:none;
        display:block;
    }

    header nav li a {
        padding:10px;
    }

    #newsletter h1, #newsletter form {
        float: none;
    }

    #newsletter input[type="email"]{
        width:100%;
        margin-bottom:5px;
    }

    #boxes .box {
        width:100%;
        float:none;
    }

    aside#sidebar, article#main-col {
        width:100%;
        float:none;
    }
}

