import { useState, useEffect } from "react";
import AnimalCard from "../components/AnimalCard";
import { motion } from "framer-motion";
import { Search } from "lucide-react";
import { clsx } from "clsx";
import api from "../services/api";

const mockAnimals = [
  {
    id: "1",
