import express from 'express';
import cors from 'cors';
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();
const app = express();
const port = 8000;

app.use(cors({ origin: 'http://localhost:5173' }));
app.use(express.json());

// Placeholder: Authentication middleware
const authenticate = (req, res, next) => {
  // TODO: Implement authentication logic
  next();
};

// Placeholder: Authorization middleware (example: check for admin role)
const authorize = (roles) => {
  return (req, res, next) => {
    // TODO: Implement authorization logic
    next();
  };
};

// --- Animal Endpoints ---

// Get all animals
app.get('/animals', authenticate, async (req, res) => {
  try {
    const animals = await prisma.animal.findMany();
    res.json(animals);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch animals' });
  }
});

// Get a specific animal by ID
app.get('/animals/:id', authenticate, async (req, res) => {
  const { id } = req.params;
  try {
    const animal = await prisma.animal.findUnique({ where: { id: parseInt(id) } });
    if (animal) {
      res.json(animal);
    } else {
      res.status(404).json({ error: 'Animal not found' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch animal' });
  }
});

// Create a new animal (requires admin role)
app.post('/animals', authenticate, authorize(['admin']), async (req, res) => {
  try {
    const animal = await prisma.animal.create({ data: req.body });
    res.status(201).json(animal);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to create animal' });
  }
});

// Update an existing animal (requires admin role)
app.put('/animals/:id', authenticate, authorize(['admin']), async (req, res) => {
  const { id } = req.params;
  try {
    const animal = await prisma.animal.update({ where: { id: parseInt(id) }, data: req.body });
    res.json(animal);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to update animal' });
  }
});

// Delete an animal (requires admin role)
app.delete('/animals/:id', authenticate, authorize(['admin']), async (req, res) => {
  const { id } = req.params;
  try {
    await prisma.animal.delete({ where: { id: parseInt(id) } });
    res.status(204).send(); // No content
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to delete animal' });
  }
});

// --- Enclosure Endpoints ---

// Get all enclosures
app.get('/enclosures', authenticate, async (req, res) => {
  try {
    const enclosures = await prisma.enclosure.findMany();
    res.json(enclosures);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch enclosures' });
  }
});

// Get a specific enclosure by ID
app.get('/enclosures/:id', authenticate, async (req, res) => {
  const { id } = req.params;
  try {
    const enclosure = await prisma.enclosure.findUnique({ where: { id: parseInt(id) } });
    if (enclosure) {
      res.json(enclosure);
    } else {
      res.status(404).json({ error: 'Enclosure not found' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch enclosure' });
  }
});

// Create a new enclosure (requires admin role)
app.post('/enclosures', authenticate, authorize(['admin']), async (req, res) => {
  try {
    const enclosure = await prisma.enclosure.create({ data: req.body });
    res.status(201).json(enclosure);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to create enclosure' });
  }
});

// Update an existing enclosure (requires admin role)
app.put('/enclosures/:id', authenticate, authorize(['admin']), async (req, res) => {
  const { id } = req.params;
  try {
    const enclosure = await prisma.enclosure.update({ where: { id: parseInt(id) }, data: req.body });
    res.json(enclosure);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to update enclosure' });
  }
});

// Delete an enclosure (requires admin role)
app.delete('/enclosures/:id', authenticate, authorize(['admin']), async (req, res) => {
  const { id } = req.params;
  try {
    await prisma.enclosure.delete({ where: { id: parseInt(id) } });
    res.status(204).send(); // No content
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to delete enclosure' });
  }
});

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

