import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { getAnimals, getEvents } from './services/api';
import AnimalCard from './components/AnimalCard';
import EventCard from './components/EventCard';
import { ArrowRight } from 'lucide-react';

export function Home() {
  const [animals, setAnimals] = useState([]);
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const fetchAnimalsAndEvents = async () => {
      const animalsData = await getAnimals();
      const eventsData = await getEvents();
      setAnimals(animalsData);
      setEvents(eventsData);
    };

    fetchAnimalsAndEvents();
  }, []);

  return (
    <motion.div
      className="container mx-auto px-4 py-8"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      {/* Hero Section */}
      <motion.section
        className="text-center mb-12"
        initial={{ y: -50, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.5 }}
      >
        <h1 className="text-4xl font-bold text-gray-800 mb-4">
          Embark on a Wild Adventure at [Zoo Name]!
        </h1>
        <p className="text-lg text-gray-600">
          Discover amazing animals, exciting events, and unforgettable
          experiences for the whole family. Explore our interactive map, plan
          your visit, and support wildlife conservation.
        </p>
        <Link
          to="/visit"
          className="inline-block mt-6 px-6 py-3 bg-green-500 text-white rounded-md hover:bg-green-600 active:scale-95 transition-transform"
        >
          Plan Your Visit
        </Link>
      </motion.section>

      {/* Featured Animals Section (Bento Grid) */}
      <motion.section
        className="mb-12"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.2, duration: 0.5 }}
      >
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">
          Meet Our Amazing Animals
        </h2>
        <p className="text-gray-600 mb-4">
          Dive into the fascinating world of wildlife! Our animal directory
          provides detailed information on each species, including their
          habitat, diet, conservation status, and fun facts.
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {animals.slice(0, 3).map((animal) => (
            <AnimalCard key={animal.animal_id} animal={animal} />
          ))}
        </div>
        <div className="mt-4 text-center">
          <Link
            to="/animals"
            className="inline-flex items-center px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 active:scale-95 transition-transform"
          >
            Explore the Animal Directory
            <ArrowRight className="ml-2" size={16} />
          </Link>
        </div>
      </motion.section>

      {/* Featured Events Section */}
      <motion.section
        className="mb-12"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.4, duration: 0.5 }}
      >
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">
          Exciting Events and Programs
        </h2>
        <p className="text-gray-600 mb-4">
          Join us for a variety of exciting events and educational programs
          throughout the year! From animal feedings and keeper talks to special
          holiday celebrations.
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {events.slice(0, 3).map((event) => (
            <EventCard key={event.event_id} event={event} />
          ))}
        </div>
        <div className="mt-4 text-center">
          <Link
            to="/events"
            className="inline-flex items-center px-4 py-2 bg-yellow-500 text-white rounded-md hover:bg-yellow-600 active:scale-95 transition-transform"
          >
            View Events Calendar
            <ArrowRight className="ml-2" size={16} />
          </Link>
        </div>
      </motion.section>

      {/* Conservation Efforts Section */}
      <motion.section
        className="text-center"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.6, duration: 0.5 }}
      >
        <h2 className="text-2xl font-semibold text-gray-800 mb-4">
          Our Commitment to Conservation
        </h2>
        <p className="text-gray-600 mb-4">
          [Zoo Name] is dedicated to protecting endangered species and
          preserving their natural habitats. Learn about our conservation
          initiatives and how we're making a difference in the world.
        </p>
        <Link
          to="/conservation"
          className="inline-block px-6 py-3 bg-green-500 text-white rounded-md hover:bg-green-600 active:scale-95 transition-transform"
        >
          Learn More About Conservation
        </Link>
      </motion.section>
    </motion.div>
  );
}

export default Home;

