prisma/schema.prisma.content:
// This is your Prisma schema file,
// learn more about it in the docs: https://pris.ly/d/prisma-schema

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = "file:./dev.db"
}

model Animal {
  id          Int      @id @default(autoincrement())
  name        String
  species     String
  description String?
  enclosure   Enclosure @relation(fields: [enclosureId], references: [id])
  enclosureId Int
}

model Enclosure {
  id          Int      @id @default(autoincrement())
  name        String
  description String?
  animals     Animal[]
}

