import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import EventCard from "../components/EventCard";
import { Calendar } from 'lucide-react';
import { getEvents } from '../services/api';

export default function Events() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchEvents = async () => {
      try {
        const data = await getEvents();
        setEvents(data);
      } catch (e) {
        setError(e);
        // Mock data fallback
        setEvents([
          {
            id: "event1",
            title: "Animal Feeding",
            description: "Watch our zookeepers feed the animals!",
            date: "2024-07-15",
            time: "10:00 AM",
            location: "Lion Enclosure",
            image: "/assets/lion.png",
          },
          {
            id: "event2",
            title: "Bird Show",
            description: "Amazing bird show at the aviary.",
            date: "2024-07-16",
            time: "2:00 PM",
            location: "Aviary",
            image: "/assets/rhino.jpg",
          },
        ]);
      } finally {
        setLoading(false);
      }
    };

    fetchEvents();
  }, []);

  if (loading) {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="flex justify-center items-center h-48"
      >
        Loading events...
      </motion.div>
    );
  }

  if (error) {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="flex justify-center items-center h-48 text-red-500"
      >
        Error: {error.message}
      </motion.div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto py-8"
