import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import ConservationProjectCard from "../components/ConservationProjectCard";
import { Link } from "react-router-dom";
import { getConservationProjects } from '../services/api';

export default function Conservation() {
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchProjects = async () => {
      try {
        const data = await getConservationProjects();
        setProjects(data);
      } catch (e) {
        console.error("Could not fetch conservation projects:", e);
        setError(e);
        // Mock data fallback
        setProjects([
          {
            id: "proj1",
            title: "Amazon Rainforest Protection",
            description:
              "Protecting the Amazon rainforest through sustainable practices.",
            image: "assets/rhino.png",
          },
          {
            id: "proj2",
            title: "Rhino Conservation in Africa",
            description:
              "Dedicated to saving the rhino population from extinction.",
            image: "assets/rhino.png",
          },
        ]);
      } finally {
        setLoading(false);
      }
    };

    fetchProjects();
  }, []);

  if (loading) {
    return (
      <div className="flex justify-center items-center h-48">
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ repeat: Infinity, duration: 2 }}
          className="text-2xl"
        >
          Loading...
        </motion.div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-red-500">
        Error: Could not load conservation projects.
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
