import { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { getAnimal } from '../services/api';

export function AnimalDetails() {
  const { animalId } = useParams();
  const [animal, setAnimal] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchAnimal = async () => {
      try {
        const animalData = await getAnimal(animalId);
        if (animalData) {
          setAnimal(animalData);
        } else {
          setError('Animal not found.');
        }
      } catch (e) {
        console.error('Could not fetch animal:', e);
        setError('Failed to load animal data.');
      } finally {
        setLoading(false);
      }
    };

    fetchAnimal();
  }, [animalId]);

  if (loading) {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="flex justify-center items-center h-screen"
      >
        <p className="text-2xl font-bold">Loading animal details...</p>
      </motion.div>
    );
  }

  if (error) {
    return (
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="flex justify-center items-center h-screen"
      >
        <p className="text-red-500 text-xl">Error: {error}</p>
      </motion.div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      className="container mx-auto py-8"
    >
      <div className="bg-white/10 backdrop-blur-lg rounded-lg shadow-md overflow-hidden">
        <img
          src={animal.image_url}
          alt={animal.name}
          className="w-full h-64 object-cover"
        />
        <div className="p-6">
          <h1 className="text-3xl font-bold text-gray-800 mb-4">{animal.name}</h1>
          <p className="text-gray-600 mb-2">
            <span className="font-semibold">Scientific Name:</span> {animal.scientific_name}
          </p>
          <p className="text-gray-600 mb-2">
            <span className="font-semibold">Habitat:</span> {animal.habitat}
          </p>
          <p className="text-gray-600 mb-2">
            <span className="font-semibold">Diet:</span> {animal.diet}
          </p>
          <p className="text-gray-600 mb-4">
            <span className="font-semibold">Conservation Status:</span> {animal.conservation_status}
          </p>
          <h2 className="text-2xl font-semibold text-gray-800 mb-2">Fun Facts</h2>
          <ul className="list-disc pl-5 text-gray-600">
            {animal.fun_facts.map((fact, index) => (
              <li key={index}>{fact}</li>
            ))}
          </ul>
        </div>
      </div>
    </motion.div>
  );
}

export default AnimalDetails;

