import express from 'express';
import cors from 'cors';
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();
const app = express();
const port = 8000;

app.use(cors({ origin: 'http://localhost:5173' }));
app.use(express.json());

// Shinchan Routes
app.get('/shinchan', async (req, res) => {
  // Placeholder for authentication/authorization
  const shinchanData = await prisma.shinchan.findMany();
  res.json(shinchanData);
});

app.post('/shinchan', async (req, res) => {
  // Placeholder for authentication/authorization
  const newShinchan = await prisma.shinchan.create({ data: req.body });
  res.json(newShinchan);
});

// Doraemon Routes
app.get('/doraemon', async (req, res) => {
  // Placeholder for authentication/authorization
  const doraemonData = await prisma.doraemon.findMany();
  res.json(doraemonData);
});

app.post('/doraemon', async (req, res) => {
  // Placeholder for authentication/authorization
  const newDoraemon = await prisma.doraemon.create({ data: req.body });
  res.json(newDoraemon);
});

// Characters Route
app.get('/characters', async (req, res) => {
    try {
        const characters = await prisma.shinchan.findMany({
            select: {
                id: true,
                name: true,
                likes: true,
            },
        });

        const doraemonCharacters = await prisma.doraemon.findMany({
            select: {
                id: true,
                name: true,
                gadget: true,
            },
        });

        // Combine characters from both models
        const allCharacters = [...characters, ...doraemonCharacters];

        res.json(allCharacters);
    } catch (error) {
        console.error('Error fetching characters:', error);
        res.status(500).json({ error: 'Failed to fetch characters' });
    }
});

// Episodes Route
app.get('/episodes', async (req, res) => {
    try {
        // Fetch episodes from both Shinchan and Doraemon models
        const shinchanEpisodes = await prisma.shinchan.findMany({
            select: {
                id: true,
                name: true,
                likes: true,
            },
        });

        const doraemonEpisodes = await prisma.doraemon.findMany({
            select: {
                id: true,
                name: true,
                gadget: true,
            },
        });

        // Combine episodes from both models
        const allEpisodes = [...shinchanEpisodes, ...doraemonEpisodes];

        res.json(allEpisodes);
    } catch (error) {
        console.error('Error fetching episodes:', error);
        res.status(500).json({ error: 'Failed to fetch episodes' });
    }
});

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

