/* src/index.css */
@import 'tailwindcss/base';
@import 'tailwindcss/components';
@import 'tailwindcss/utilities';

/* Global Styles */
:root {
  --primary-color: #FFC107; /* Yellow */
  --secondary-color: #E91E63; /* Pink */
  --accent-color: #2196F3; /* Blue */
  --text-primary: #333; /* Dark Gray */
  --text-secondary: #FFF; /* White */
  --base-spacing: 1rem;
  --transition-duration: 0.3s;
  --transition-easing: cubic-bezier(0.4, 0, 0.2, 1);
}

body {
  font-family: 'Kalam', cursive, sans-serif;
  background-color: var(--primary-color);
  color: var(--text-primary);
  line-height: 1.6;
  margin: 0;
  padding: 0;
  overflow-x: hidden; /* Prevent horizontal scroll */
}

/* Typography */
h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.05em;
}

h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.2;
}

p {
  font-size: clamp(1rem, 2vw, 1.2rem);
  color: rgba(51, 51, 51, 0.8);
}

a {
  color: var(--accent-color);
  text-decoration: none;
  transition: color var(--transition-duration) var(--transition-easing);
}

a:hover {
  color: darken(var(--accent-color), 10%);
}

/* Layout & Spacing */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--base-spacing);
}

/* Buttons & Interactive Elements */
button, .button {
  background-color: var(--secondary-color);
  color: var(--text-secondary);
  font-weight: 700;
  padding: calc(var(--base-spacing) / 2) var(--base-spacing);
  border-radius: 9999px;
  border: none;
  cursor: pointer;
  transition: transform var(--transition-duration) var(--transition-easing), box-shadow var(--transition-duration) var(--transition-easing);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

button:hover, .button:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 10px rgba(0, 0, 0, 0.2);
}

/* Cards & Content Blocks */
.card {
  background-color: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(10px);
  border-radius: 1rem;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.05);
  padding: var(--base-spacing);
  transition: transform var(--transition-duration) var(--transition-easing);
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.1);
}

/* Header and Footer */
header, footer {
  background-color: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(12px);
  padding: var(--base-spacing);
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
}

/* Navigation */
nav a {
  display: inline-block;
  padding: calc(var(--base-spacing) / 4) calc(var(--base-spacing) / 2);
  border-radius: 0.5rem;
  transition: background-color var(--transition-duration) var(--transition-easing), color var(--transition-duration) var(--transition-easing);
}

nav a:hover {
  background-color: rgba(0, 0, 0, 0.05);
}

nav a.active {
  color: var(--secondary-color);
  font-weight: bold;
}

/* Utilities */
.text-center {
  text-align: center;
}

.mb-4 {
  margin-bottom: calc(var(--base-spacing) / 2);
}

.mt-8 {
  margin-top: calc(var(--base-spacing) * 2);
}

/* Responsive Design */
@media (max-width: 768px) {
  .container {
    padding: calc(var(--base-spacing) / 2);
  }

  h1 {
    font-size: 3rem;
  }

  h2 {
    font-size: 2.2rem;
  }
}

/* --- Reveal on Scroll Animation --- */
.reveal {
  position: relative;
  transform: translateY(150px);
  opacity: 0;
  transition: 1s all ease;
}

.reveal.active {
  transform: translateY(0);
  opacity: 1;
}

.reveal.active:nth-child(1) {
  transition-delay: 0.1s;
}

.reveal.active:nth-child(2) {
  transition-delay: 0.2s;
}

.reveal.active:nth-child(3) {
  transition-delay: 0.3s;
}

.reveal.active:nth-child(4) {
  transition-delay: 0.4s;
}

