import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Link } from "react-router-dom"; // Import Link
import { EpisodeCard } from "../components/EpisodeCard.jsx";
import { getAllEpisodes } from "../services/api.js";

const mockEpisodeData = [
  {
    id: "101",
    title: "Shinchan Goes to the Beach",
    season: "1",
    episode_number: "1",
    summary:
      "Sun, sand, and Shinchan's signature brand of chaos! The Nohara family hits the beach for a day of unforgettable fun.",
    image_url: "/assets/episode1.png",
  },
  {
    id: "102",
    title: "Shinchan and the Lost Puppy",
    season: "1",
    episode_number: "2",
    summary:
      "A lost puppy turns into a hilarious adventure as Shinchan tries his best (or worst!) to take care of it.",
    image_url: "/assets/episode2.png",
  },
];

export default function EpisodesPage() {
  const [episodes, setEpisodes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchEpisodes = async () => {
      try {
        const data = await getAllEpisodes();
        setEpisodes(data);
      } catch (err) {
        console.error("Error fetching episodes:", err);
        setError(err.message || "Failed to load episodes.");
        setEpisodes(mockEpisodeData); // Fallback to mock data
      } finally {
        setLoading(false);
      }
    };

    fetchEpisodes();
  }, []);

  return (
    <motion.div
      className="container mx-auto p-4"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.7 }}
    >
      <h1 className="text-3xl font-bold text-red-600 mb-4">Episodes</h1>

      {loading && <p className="text-gray-600">Loading episodes...</p>}

      {error && (
        <div className="text-red-500 mb-4">
          Error: {error} - Displaying mock data.
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {episodes.map((episode) => (
          <EpisodeCard key={episode.id} episode={episode} />
        ))}
      </div>
    </motion.div>
  );
}

