    --transition-duration: 0.3s;
    --transition-easing: cubic-bezier(0.4, 0, 0.2, 1); /* Standard easing */
}

/* Base Styles */
body {
    font-family: var(--font-family-primary);
    background-color: var(--bg-light);
    color: var(--text-primary);
    line-height: 1.6;
