    font-size: clamp(2rem, 4vw, 3rem);
}

p {
    font-size: clamp(1rem, 2vw, 1.2rem); /* Responsive paragraph sizes */
}

ul, ol {
    padding-left: 1.5rem;
    margin-bottom: 1rem;
}

/* Utility Classes */
.container {
    @apply mx-auto px-4;
    max-width: 1200px; /* Standard container width */
}

.text-primary {
    color: var(--text-primary);
}

.text-secondary {
    color: var(--text-secondary);
}

/* Button Styles */
.btn {
    @apply font-bold py-2 px-4 rounded shadow-md transition-colors duration-300;
    transition: all var(--transition-duration) var(--transition-easing);
}

.btn-primary {
    @apply bg-orange-500 hover:bg-orange-700 text-white;
}

.btn-secondary {
    @apply bg-gray-500 hover:bg-gray-700 text-white;
}

/* Glassmorphism Effect */
.glassmorphism {
    background: rgba(255, 255, 255, 0.1); /* Adjusted opacity */
    border-radius: 1rem;
    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.15); /* Increased shadow */
    backdrop-filter: blur(12px); /* Adjusted blur */
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.2); /* Adjusted border */
}

/* Reveal on Scroll Effect */
.reveal {
    opacity: 0;
    transform: translateY(20px);
    transition: transform var(--transition-duration) var(--transition-easing), opacity var(--transition-duration) var(--transition-easing);
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}

/* Specific delays for cascaded entry */
.reveal:nth-child(1) { transition-delay: 0.1s; }
.reveal:nth-child(2) { transition-delay: 0.2s; }
.reveal:nth-child(3) { transition-delay: 0.3s; }
.reveal:nth-child(4) { transition-delay: 0.4s; }
