import { BrowserRouter as Router, Route, Routes, NavLink } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';
import Home from './pages/Home';
import MenuPage from './pages/Menu';
import LocationPage from './pages/Location';
import CateringPage from './pages/Catering';
import AboutPage from './pages/About';
import ContactPage from './pages/Contact';
import OrderPage from './pages/Order';

function Header() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
  };

  return (
    <motion.header
      className="header"
      initial={{ opacity: 0, y: -50 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, ease: "var(--transition-easing)" }}
    >
      <div className="container mx-auto flex items-center justify-between px-4">
        <NavLink to="/" className="text-2xl font-bold hover:text-secondary">
          Indian Street Flavors
        </NavLink>

        {/* Mobile Menu Button */}
        <button
          className="md:hidden text-white focus:outline-none"
          onClick={toggleMobileMenu}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>

        {/* Navigation Links (Desktop) */}
        <nav className="hidden md:flex space-x-6">
          <NavLink to="/" className={({ isActive }) => isActive ? 'text-secondary' : 'hover:text-secondary'}>
            Home
          </NavLink>
          <NavLink to="/about" className={({ isActive }) => isActive ? 'text-secondary' : 'hover:text-secondary'}>
            About
          </NavLink>
          <NavLink to="/menu" className={({ isActive }) => isActive ? 'text-secondary' : 'hover:text-secondary'}>
            Menu
          </NavLink>
          <NavLink to="/location" className={({ isActive }) => isActive ? 'text-secondary' : 'hover:text-secondary'}>
            Location
          </NavLink>
          <NavLink to="/catering" className={({ isActive }) => isActive ? 'text-secondary' : 'hover:text-secondary'}>
            Catering
          </NavLink>
          <NavLink to="/contact" className={({ isActive }) => isActive ? 'text-secondary' : 'hover:text-secondary'}>
            Contact
          </NavLink>
          <NavLink to="/order" className={({ isActive }) => isActive ? 'text-secondary' : 'hover:text-secondary'}>
            Order
          </NavLink>
        </nav>
      </div>

      {/* Mobile Menu (Conditional Rendering) */}
      {isMounted && isMobileMenuOpen && (
        <motion.div
          className="mobile-menu md:hidden absolute top-full left-0 w-full bg-orange-600/90 backdrop-blur-lg py-4 px-6 flex flex-col items-center"
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          transition={{ duration: 0.3, ease: "var(--transition-easing)" }}
        >
          <NavLink to="/" className="block py-2 hover:text-orange-200" onClick={closeMobileMenu}>
            Home
          </NavLink>
          <NavLink to="/about" className="block py-2 hover:text-orange-200" onClick={closeMobileMenu}>
            About
          </NavLink>
          <NavLink to="/menu" className="block py-2 hover:text-orange-200" onClick={closeMobileMenu}>
            Menu
          </NavLink>
          <NavLink to="/location" className="block py-2 hover:text-orange-200" onClick={closeMobileMenu}>
            Location
          </NavLink>
          <NavLink to="/catering" className="block py-2 hover:text-orange-200" onClick={closeMobileMenu}>
            Catering
          </NavLink>
          <NavLink to="/contact" className="block py-2 hover:text-orange-200" onClick={closeMobileMenu}>
            Contact
          </NavLink>
          <NavLink to="/order" className="block py-2 hover:text-orange-200" onClick={closeMobileMenu}>
            Order
          </NavLink>
        </motion.div>
      )}
    </motion.header>
  );
}

function Footer() {
  return (
    <footer className="footer">
      <div className="container mx-auto text-center">
        <p>&copy; 2024 Indian Street Flavors. All rights reserved.</p>
        <div className="flex justify-center mt-2 space-x-4">
          <a href="#" className="hover:text-orange-500">
            {/* Replace with actual social media links and icons */}
            Facebook
          </a>
          <a href="#" className="hover:text-orange-500">
            Twitter
          </a>
          <a href="#" className="hover:text-orange-500">
            Instagram
          </a>
        </div>
      </div>
    </footer>
  );
}

export default function App() {
  return (
    <Router>
      <div className="min-h-screen flex flex-col">
        <Header />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/menu" element={<MenuPage />} />
            <Route path="/location" element={<LocationPage />} />
            <Route path="/catering" element={<CateringPage />} />
            <Route path="/contact" element={<ContactPage />} />
            <Route path="/order" element={<OrderPage />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

