];

const getMenuItems = async () => {
    try {
        const response = await fetch(`${API_BASE_URL}/menu`);
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        return await response.json();
    } catch (error) {
        console.error("Error fetching menu items:", error);
        return mockMenuItems; // Return mock data on error
    }
};

const addToCart = async (item) => {
    try {
        const response = await fetch(`${API_BASE_URL}/cart/add`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(item),
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        return await response.json();
    } catch (error) {
        console.error("Error adding to cart:", error);
        // Consider a more sophisticated fallback, like local storage
        return { success: false, message: "Failed to add to cart." };
    }
};

const placeOrder = async (orderData) => {
    try {
        const response = await fetch(`${API_BASE_URL}/order/place`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(orderData),
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        return await response.json();
    } catch (error) {
        console.error("Error placing order:", error);
        return { success: false, message: "Failed to place order." };
    }
};

export { getMenuItems, addToCart, placeOrder };

prisma/schema.prisma.content:
// prisma/schema.prisma

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = "file:./dev.db"
}

model MenuItem {
  id          Int      @id @default(autoincrement())
  name        String
  description String
  price       Float
  image       String? // URL to the image
  orderItems  OrderItem[]
}

model Order {
  id        Int      @id @default(autoincrement())
  orderDate DateTime
  total     Float
  orderItems OrderItem[]
}

model OrderItem {
  id Int @id @default(autoincrement())
  order   Order @relation(fields: [orderId], references: [id])
  orderId Int
  menuItem   MenuItem @relation(fields: [menuItemId], references: [id]) // Relation to MenuItem
  menuItemId Int // Foreign key for MenuItem
  quantity Int

  @@unique([orderId, menuItemId])
}

