// services/server.js
const express = require('express');
const app = express();
const port = 3001;
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

app.use(express.json());

// Placeholder: Authentication middleware
const authenticate = (req, res, next) => {
  // TODO: Implement actual authentication logic
  next();
};

// Placeholder: Authorization middleware
const authorize = (role) => {
  return (req, res, next) => {
    // TODO: Implement actual authorization logic based on role
    next();
  };
};

// GET: Retrieve all properties
app.get('/properties', async (req, res) => {
  try {
    const properties = await prisma.property.findMany();
    res.json(properties);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to retrieve properties' });
  }
});

// GET: Retrieve a specific property by ID
app.get('/properties/:id', async (req, res) => {
  const { id } = req.params;
  try {
    const property = await prisma.property.findUnique({
      where: { id: parseInt(id) },
    });
    if (property) {
      res.json(property);
    } else {
      res.status(404).json({ error: 'Property not found' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to retrieve property' });
  }
});

// POST: Create a new property (requires authentication and authorization)
app.post('/properties', authenticate, authorize('admin'), async (req, res) => {
  try {
    const property = await prisma.property.create({
      data: req.body,
    });
    res.status(201).json(property);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to create property' });
  }
});

// POST: Submit contact form
app.post('/contact', async (req, res) => {
  try {
    const contactSubmission = await prisma.contactSubmission.create({
      data: req.body,
    });
    res.status(201).json(contactSubmission);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to submit contact form' });
  }
});

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

