import { useState } from "react";
import { motion } from "framer-motion";
import { CheckCircle, AlertTriangle } from 'lucide-react';

export default function ContactForm() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [message, setMessage] = useState("");
  const [nameError, setNameError] = useState("");
  const [emailError, setEmailError] = useState("");
  const [messageError, setMessageError] = useState("");
  const [success, setSuccess] = useState(false);
  const [failure, setFailure] = useState(false);

  const validateForm = () => {
    let isValid = true;

    if (!name.trim()) {
      setNameError("Name is required");
      isValid = false;
    } else {
      setNameError("");
    }

    if (!email.trim()) {
      setEmailError("Email is required");
      isValid = false;
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setEmailError("Invalid email format");
      isValid = false;
    } else {
      setEmailError("");
    }

    if (!message.trim()) {
      setMessageError("Message is required");
      isValid = false;
    } else {
      setMessageError("");
    }

    return isValid;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (validateForm()) {
      try {
        const response = await fetch("/api/contact", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ name, email, message }),
        });

        if (response.ok) {
          setSuccess(true);
          setFailure(false);
          setName("");
          setEmail("");
          setMessage("");
          setNameError("");
          setEmailError("");
          setMessageError("");
          setTimeout(() => setSuccess(false), 3000); // Clear success message after 3 seconds
        } else {
          setFailure(true);
          setSuccess(false);
          setTimeout(() => setFailure(false), 5000); // Clear failure message after 5 seconds
        }
      } catch (error) {
        console.error("Form submission error:", error);
        setFailure(true);
        setSuccess(false);
        setTimeout(() => setFailure(false), 5000); // Clear failure message after 5 seconds
      }
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="bg-white/10 backdrop-blur-lg rounded-lg shadow-lg p-8 max-w-lg mx-auto"
    >
      <h2 className="text-2xl font-semibold text-white mb-4">Contact Us</h2>
      {success && (
        <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded relative mb-4" role="alert">
          <CheckCircle className="w-6 h-6 inline mr-2" />
          <span className="block sm:inline">Message sent successfully!</span>
        </div>
      )}
      {failure && (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-4" role="alert">
          <AlertTriangle className="w-6 h-6 inline mr-2" />
          <span className="block sm:inline">Failed to send message. Please try again later.</span>
        </div>
      )}
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label htmlFor="name" className="block text-white text-sm font-bold mb-2">
            Name
          </label>
          <input
            type="text"
            id="name"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline bg-white/50 backdrop-blur-sm"
            placeholder="Your Name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          {nameError && <p className="text-red-500 text-xs italic">{nameError}</p>}
        </div>
        <div>
          <label htmlFor="email" className="block text-white text-sm font-bold mb-2">
            Email
          </label>
          <input
            type="email"
            id="email"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline bg-white/50 backdrop-blur-sm"
            placeholder="Your Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          {emailError && <p className="text-red-500 text-xs italic">{emailError}</p>}
        </div>
        <div>
          <label htmlFor="message" className="block text-white text-sm font-bold mb-2">
            Message
          </label>
          <textarea
            id="message"
            rows="4"
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline bg-white/50 backdrop-blur-sm"
            placeholder="Your Message"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
          />
          {messageError && <p className="text-red-500 text-xs italic">{messageError}</p>}
        </div>
        <div className="flex items-center justify-between">
          <motion.button
            className="bg-gold-500 hover:bg-gold-700 text-black font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline hover:scale-105 active:scale-95 transition-transform duration-200"
            type="submit"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            Send Message
          </motion.button>
        </div>
      </form>
    </motion.div>
  );
}

