import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";
import { Hero } from "../components/Hero.jsx";
import { PropertyCard } from "../components/PropertyCard.jsx";
import { ContactForm } from "../components/ContactForm.jsx";
import {
  getFeaturedProperties,
  fetchProperties,
} from "../services/api.js";

export default function Home() {
  const [featuredProperties, setFeaturedProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const loadFeaturedProperties = async () => {
      try {
        setLoading(true);
        const properties = await getFeaturedProperties();
        setFeaturedProperties(properties);
      } catch (err) {
        console.error("Failed to load featured properties:", err);
        setError("Failed to load properties. Please try again later.");
        setFeaturedProperties([
          {
            id: "mock1",
            title: "Mock Estate 1",
            price: "$2,500,000",
            imageUrl: "/assets/property1.jpg",
            location: "New York, NY",
          },
          {
            id: "mock2",
            title: "Mock Estate 2",
            price: "$3,800,000",
            imageUrl: "/assets/property2.jpg",
            location: "Los Angeles, CA",
          },
        ]);
      } finally {
        setLoading(false);
      }
    };

    loadFeaturedProperties();
  }, []);

  const fadeIn = {
    initial: { opacity: 0 },
    animate: { opacity: 1 },
    transition: { duration: 0.8, ease: "easeOut" },
  };

  return (
    <motion.div
      className="bg-black text-white min-h-screen overflow-hidden"
      variants={fadeIn}
      initial="initial"
      animate="animate"
    >
      <Hero />

      {/* Featured Properties Section */}
      <section className="py-16 px-4 md:px-8 lg:px-16">
        <motion.h2
          className="text-3xl md:text-4xl font-bold text-center mb-8"
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
        >
          Featured Properties
        </motion.h2>

        {loading && (
          <div className="text-center text-gray-500">Loading properties...</div>
        )}
        {error && <div className="text-center text-red-500">{error}</div>}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {featuredProperties.map((property) => (
            <PropertyCard key={property.id} property={property} />
          ))}
        </div>

        <div className="text-center mt-8">
          <Link
            to="/properties"
            className="inline-block bg-gold-500 text-black py-2 px-6 rounded-full hover:bg-gold-700 transition duration-300"
          >
            View All Properties
          </Link>
        </div>
      </section>

      {/* Contact Section */}
