// src/services/api.js

const API_BASE_URL = 'http://localhost:3000'; // Adjust if your server runs on a different port

// Mock data for properties (fallback in case API fails)
const mockProperties = [
    { id: 1, name: 'Luxury Penthouse', price: 2500000, imageUrl: '/assets/property1.jpg' },
    { id: 2, name: 'Elegant Townhouse', price: 1800000, imageUrl: '/assets/property2.jpg' },
];

const mockAgents = [
    { id: 1, name: 'John Doe', title: 'Senior Agent', imageUrl: '/assets/agent1.jpg' },
]


async function getProperties() {
    try {
        const response = await fetch(`${API_BASE_URL}/properties`);
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        return data;
    } catch (error) {
        console.error("Error fetching properties:", error);
        return mockProperties; // Return mock data on error
    }
}

async function getAgents() {
    try {
        const response = await fetch(`${API_BASE_URL}/agents`);
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        return data;
    } catch (error) {
        console.error("Error fetching agents:", error);
        return mockAgents; // Return mock data on error
    }
}

async function submitContactForm(data) {
    try {
        const response = await fetch(`${API_BASE_URL}/contact`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(data),
        });

        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }

        return await response.json(); // Or handle success message
    } catch (error) {
        console.error("Error submitting contact form:", error);
        return { success: false, message: 'Failed to submit form. Please try again.' }; // Handle error case
    }
}

export { getProperties, getAgents, submitContactForm };

