import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";
import { MapPin, Bed, Bath, SquareFoot } from 'lucide-react';

import { getProperties } from "../services/api";

export default function Properties() {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchProperties = async () => {
      try {
        const data = await getProperties();
        setProperties(data);
        setLoading(false);
      } catch (err) {
        console.error("Error fetching properties:", err);
        setError(err.message || "Failed to load properties.");
        setLoading(false);
      }
    };

    fetchProperties();
  }, []);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        delay: 0.2,
        duration: 0.8,
        staggerChildren: 0.2,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 50 },
    visible: { opacity: 1, y: 0 },
  };

  if (loading) {
    return (
      <motion.div
        className="bg-black text-white min-h-screen flex justify-center items-center"
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        exit={{ opacity: 0, transition: { duration: 0.3 } }}
      >
        <motion.p variants={itemVariants} className="text-2xl">
          Loading properties...
        </motion.p>
      </motion.div>
    );
  }

  if (error) {
    return (
      <motion.div
        className="bg-black text-white min-h-screen flex justify-center items-center"
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        exit={{ opacity: 0, transition: { duration: 0.3 } }}
      >
        <motion.p variants={itemVariants} className="text-red-500 text-xl">
          Error: {error}
        </motion.p>
      </motion.div>
    );
  }

  return (
    <motion.div
      className="bg-black text-white min-h-screen py-12"
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      exit={{ opacity: 0, transition: { duration: 0.3 } }}
    >
      <div className="container mx-auto px-4">
        <motion.h1
          variants={itemVariants}
          className="text-4xl font-bold text-center mb-8"
        >
          Exclusive Property Listings
