        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {properties.map((property) => (
            <motion.div
              key={property.id}
              variants={itemVariants}
              className="rounded-lg overflow-hidden shadow-md bg-gray-900 hover:scale-105 transition-transform duration-300"
            >
              <img
                src={property.image}
