            "room_id": "103",
            "room_type": "Suite",
            "description": "A luxurious suite with a king-size bed, separate living area, private bathroom, balcony, and panoramic views.",
            "amenities": [
              "Air conditioning",
              "Free Wi-Fi",
              "TV",
              "Mini-fridge",
              "Hairdryer",
              "Balcony",
              "Living Area",
              "Jacuzzi"
            ],
            "price_per_night": 300,
            "images": [
              "room3_1.jpg",
              "room3_2.jpg"
            ],
            "availability": {
              "2024-01-01": false,
              "2024-01-02": true,
              "2024-01-03": false
            }
          }
        ]);
      } finally {
        setLoading(false);
      }
    };

    fetchRooms();
  }, []);

  // Pagination logic
  const indexOfLastRoom = currentPage * roomsPerPage;
  const indexOfFirstRoom = indexOfLastRoom - roomsPerPage;
  const currentRooms = rooms.slice(indexOfFirstRoom, indexOfLastRoom);

  const totalPages = Math.ceil(rooms.length / roomsPerPage);

  const handlePageChange = (newPage) => {
    setCurrentPage(newPage);
    setSearchParams({ page: newPage }); // Update the URL
  };


  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="py-12 bg-white"
    >
      <div className="container mx-auto px-4">
        <h2 className="text-3xl font-bold text-gray-800 mb-8 text-center">
          Our Rooms
        </h2>

        {loading && <p className="text-center">Loading rooms...</p>}
        {error && (
          <p className="text-center text-red-500">
            Error: {error.message}
          </p>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {currentRooms.map((room) => (
            <RoomCard key={room.room_id} room={room} />
          ))}
        </div>

        {/* Pagination */}
        <div className="flex justify-center mt-8 space-x-2">
          <button
            onClick={() => handlePageChange(currentPage - 1)}
            disabled={currentPage === 1}
            className={`px-4 py-2 rounded-md text-gray-700 bg-gray-200 hover:bg-gray-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center`}
          >
            <ArrowLeft className="mr-1 w-4 h-4" /> Previous
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
            <button
              key={page}
              onClick={() => handlePageChange(page)}
              className={`px-4 py-2 rounded-md ${
                currentPage === page
                  ? "bg-brown-500 text-white"
                  : "text-gray-700 bg-gray-200 hover:bg-gray-300"
              }`}
            >
              {page}
            </button>
          ))}
          <button
            onClick={() => handlePageChange(currentPage + 1)}
            disabled={currentPage === totalPages}
            className={`px-4 py-2 rounded-md text-gray-700 bg-gray-200 hover:bg-gray-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center`}
          >
            Next <ArrowRight className="ml-1 w-4 h-4" />
          </button>
        </div>
      </div>
    </motion.div>
  );
}

