    ],
    "availability": {
      "2024-01-01": false,
      "2024-01-02": true,
      "2024-01-03": false
    }
  }
];

const API_BASE_URL = process.env.NODE_ENV === 'production' ? '/api' : 'http://localhost:3000/api';

async function fetchHotelDetails() {
  try {
    const response = await fetch(`${API_BASE_URL}/hotel`);
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    return await response.json();
  } catch (error) {
    console.error("Error fetching hotel details:", error);
    // In case of error, return mock data
    return {
      name: "Bella Italia Hotel",
      description: "Experience the heart of Italy.",
      location: "Florence"
    };
  }
}

async function fetchRoomAvailability(roomId, checkInDate, checkOutDate) {
  try {
    const response = await fetch(
      `${API_BASE_URL}/rooms/${roomId}/availability?checkInDate=${checkInDate}&checkOutDate=${checkOutDate}`
    );

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error(`Error fetching availability for room ${roomId}:`, error);
    // Mock data for availability
    return {
      roomId: roomId,
      available: true,
      message: "Mock availability data"
    };
  }
}

async function getAllRooms() {
  try {
    const response = await fetch(`${API_BASE_URL}/rooms`);
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    return await response.json();
  } catch (error) {
    console.error("Error fetching all rooms:", error);
    return MOCK_ROOM_DATA; // Return mock data in case of an error
  }
}


async function createBooking(bookingData) {
  try {
    const response = await fetch(`${API_BASE_URL}/bookings`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(bookingData),
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error("Error creating booking:", error);
    // Return a mock booking confirmation
    return {
      success: false,
      message: "Mock booking failed",
      bookingId: null,
    };
  }
}

export { fetchHotelDetails, fetchRoomAvailability, getAllRooms, createBooking };

prisma/schema.prisma.content:
// prisma/schema.prisma
datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Hotel {
  id          Int       @id @default(autoincrement())
  name        String
  description String?
  address     String
  city        String
  rooms       Room[]
}

model Room {
  id          Int       @id @default(autoincrement())
  hotelId     Int
  number      Int
  type        String
  price       Float
  hotel       Hotel     @relation(fields: [hotelId], references: [id])
  bookings    Booking[]
}

model Booking {
  id        Int      @id @default(autoincrement())
  roomId    Int
  startDate DateTime
  endDate   DateTime
  guestName String
  room      Room     @relation(fields: [roomId], references: [id])
}

