          Exquisite Dining Experiences
        </motion.h1>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {diningOptions.map((dining) => (
            <DiningCard key={dining.id} dining={dining} />
          ))}
        </div>
      </div>
    </motion.div>
  );
}

