import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { Bed, Bathtub, Wifi, Tv, Coffee } from 'lucide-react';
import { clsx } from 'clsx';

export default function RoomCard({ room }) {
  const { room_id, room_type, description, amenities, price_per_night, images } = room;

  const getAmenityIcon = (amenity) => {
    switch (amenity.toLowerCase()) {
      case 'air conditioning':
        return null; // No direct icon
      case 'free wi-fi':
        return <Wifi className="h-5 w-5 text-gray-500" />;
      case 'tv':
        return <Tv className="h-5 w-5 text-gray-500" />;
      case 'mini-fridge':
        return <Coffee className="h-5 w-5 text-gray-500" />;
      case 'hairdryer':
        return null; // No direct icon
      case 'bathtub':
        return <Bathtub className="h-5 w-5 text-gray-500" />;
      case 'balcony':
        return null; // No direct icon
      case 'living area':
        return null; // No direct icon
      case 'jacuzzi':
        return <Bathtub className="h-5 w-5 text-gray-500" />;
      case 'double bed':
      case 'king-size bed':
        return <Bed className="h-5 w-5 text-gray-500" />;
      default:
        return null;
    }
  };

  return (
    <motion.div
      className="relative flex flex-col rounded-lg shadow-md overflow-hidden bg-white/10 backdrop-blur-lg"
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.95 }}
      transition={{ duration: 0.2 }}
    >
      <img
        src={`/assets/${images[0]}`} // Assuming first image is the thumbnail
        alt={room_type}
        className="w-full h-48 object-cover"
      />

      <div className="p-4">
        <h3 className="text-xl font-semibold text-gray-800">{room_type}</h3>
        <p className="mt-2 text-gray-600">{description}</p>

        <div className="mt-4">
          <h4 className="text-md font-semibold text-gray-700">Amenities</h4>
          <div className="flex flex-wrap gap-2 mt-2">
            {amenities.map((amenity, index) => (
              <div key={index} className="flex items-center space-x-1 text-sm text-gray-500">
                {getAmenityIcon(amenity)}
                <span>{amenity}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="mt-4 flex items-center justify-between">
          <span className="text-lg font-bold text-gray-900">â¬{price_per_night} / night</span>
          <Link to={`/rooms/${room_id}`} className="bg-brown-500 hover:bg-brown-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline">
            View Details
          </Link>
        </div>
      </div>
