// services/server.js
const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();
const port = 3000;

app.use(express.json());

// Placeholder middleware for authentication (replace with actual auth)
const authenticate = (req, res, next) => {
  // TODO: Implement actual authentication logic
  console.log('Authentication placeholder');
  next();
};

// Menu Items Endpoints

// Get all menu items
app.get('/menu', async (req, res) => {
  try {
    const menuItems = await prisma.menuItem.findMany();
    res.json(menuItems);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch menu items' });
  }
});

// Get a specific menu item by ID
app.get('/menu/:id', async (req, res) => {
  const { id } = req.params;
  try {
    const menuItem = await prisma.menuItem.findUnique({
      where: { id: parseInt(id) },
    });
    if (menuItem) {
      res.json(menuItem);
    } else {
      res.status(404).json({ error: 'Menu item not found' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch menu item' });
  }
});

// Create a new menu item (requires authentication)
app.post('/menu', authenticate, async (req, res) => {
  try {
    const newMenuItem = await prisma.menuItem.create({
      data: req.body,
    });
    res.status(201).json(newMenuItem);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to create menu item' });
  }
});

// Update a menu item (requires authentication)
app.put('/menu/:id', authenticate, async (req, res) => {
  const { id } = req.params;
  try {
    const updatedMenuItem = await prisma.menuItem.update({
      where: { id: parseInt(id) },
      data: req.body,
    });
    res.json(updatedMenuItem);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to update menu item' });
  }
});

// Delete a menu item (requires authentication)
app.delete('/menu/:id', authenticate, async (req, res) => {
  const { id } = req.params;
  try {
    await prisma.menuItem.delete({
      where: { id: parseInt(id) },
    });
    res.status(204).send(); // No content
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to delete menu item' });
  }
});

// Orders Endpoints

// Create a new order
app.post('/orders', async (req, res) => {
  try {
    const newOrder = await prisma.order.create({
      data: req.body,
    });
    res.status(201).json(newOrder);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to create order' });
  }
});

// Get all orders
app.get('/orders', authenticate, async (req, res) => {
    try {
      const orders = await prisma.order.findMany();
      res.json(orders);
    } catch (error) {
      console.error(error);
      res.status(500).json({ error: 'Failed to fetch orders' });
    }
  });

// Get a specific order by ID
app.get('/orders/:id', authenticate, async (req, res) => {
  const { id } = req.params;
  try {
    const order = await prisma.order.findUnique({
      where: { id: parseInt(id) },
    });
    if (order) {
      res.json(order);
    } else {
      res.status(404).json({ error: 'Order not found' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch order' });
  }
});


app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

