prisma/schema.prisma.content:
// prisma/schema.prisma
datasource db {
  provider = "sqlite"
  url      = "file:./dev.db"
}

generator client {
  provider = "prisma-client-js"
}

model MenuItem {
  id          Int       @id @default(autoincrement())
  name        String
  description String?
  price       Float
  image       String?
  category    String?   // e.g., "Appetizer", "Main Course", "Dessert"
}

model Order {
    id         Int      @id @default(autoincrement())
    createdAt  DateTime @default(now())
    total      Float
    items      OrderItem[]
}

model OrderItem {
    id          Int      @id @default(autoincrement())
    orderId     Int
    menuItemId  Int
    quantity    Int
    order       Order    @relation(fields: [orderId], references: [id])
}

