import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { MapPin } from 'lucide-react';
import { GoogleMap, LoadScript, Marker } from '@react-google-maps/api'; // Ensure this is installed: npm install @react-google-maps/api

const mockLocations = [
  { id: 1, name: 'Downtown Kart', lat: 34.052235, lng: -118.243683, address: '123 Main St, Los Angeles, CA' },
  { id: 2, name: 'Beachside Kart', lat: 33.959464, lng: -118.430235, address: '456 Ocean Ave, Santa Monica, CA' },
];

export default function Locations() {
  const [locations, setLocations] = useState(mockLocations); // Use mock data initially
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchLocations = async () => {
      try {
        const response = await fetch('/locations'); // Assuming your server endpoint is /locations
        if (!response.ok) {
          throw new Error('Failed to fetch locations');
        }
        const data = await response.json();
        setLocations(data);
      } catch (err) {
        console.error('Error fetching locations:', err);
        setError(err.message);
        // Fallback to mock data in case of API failure
        setLocations(mockLocations);
      }
    };

    fetchLocations();
  }, []);

  const mapStyles = {
    height: '400px',
    width: '100%',
  };

  const defaultCenter = {
    lat: 34.052235, // Los Angeles latitude
    lng: -118.243683, // Los Angeles longitude
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto py-12 px-4 sm:px-6 lg:px-8"
    >
      <h1 className="text-3xl font-bold text-gray-800 mb-8">Our Locations</h1>

      {error && (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-4" role="alert">
          <strong className="font-bold">Error!</strong>
          <span className="block sm:inline"> {error} Displaying mock locations.</span>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* List View */}
        <div>
          <h2 className="text-xl font-semibold text-gray-700 mb-4">List View</h2>
          <ul>
            {locations.map((location) => (
              <motion.li
                key={location.id}
                className="bg-white shadow rounded-lg p-4 mb-2 hover:scale-105 active:scale-95 transition-transform duration-200"
              >
                <div className="flex items-center space-x-3">
                  <MapPin className="text-gray-500 h-5 w-5" />
                  <div>
                    <h3 className="text-lg font-medium text-gray-800">{location.name}</h3>
                    <p className="text-gray-600">{location.address}</p>
                  </div>
                </div>
              </motion.li>
            ))}
          </ul>
        </div>

        {/* Map View */}
        <div>
          <h2 className="text-xl font-semibold text-gray-700 mb-4">Map View</h2>
          <LoadScript googleMapsApiKey={process.env.REACT_APP_GOOGLE_MAPS_API_KEY || ""}>
            <GoogleMap mapContainerStyle={mapStyles} defaultCenter={defaultCenter} zoom={12}>
              {locations.map((location) => (
                <Marker
                  key={location.id}
                  position={{ lat: location.lat, lng: location.lng }}
                  label={location.name}
                />
              ))}
            </GoogleMap>
          </LoadScript>
        </div>
      </div>
    </motion.div>
  );
}

