// services/server.js

const express = require('express');
const { PrismaClient } = require('@prisma/client');
const cors = require('cors');

const prisma = new PrismaClient();
const app = express();
const port = process.env.PORT || 3001;

app.use(cors());
app.use(express.json());

// --- Waffle Endpoints ---

// GET all waffles
app.get('/waffles', async (req, res) => {
  try {
    const waffles = await prisma.waffle.findMany();
    res.json(waffles);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch waffles' });
  }
});

// GET a specific waffle by ID
app.get('/waffles/:id', async (req, res) => {
  const { id } = req.params;
  try {
    const waffle = await prisma.waffle.findUnique({
      where: { id: parseInt(id) },
    });
    if (waffle) {
      res.json(waffle);
    } else {
      res.status(404).json({ error: 'Waffle not found' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch waffle' });
  }
});

// POST a new waffle
app.post('/waffles', async (req, res) => {
  const { name, description, imageUrl } = req.body;
  try {
    const newWaffle = await prisma.waffle.create({
      data: {
        name,
        description,
        imageUrl,
      },
    });
    res.status(201).json(newWaffle);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to create waffle' });
  }
});

// PUT (update) an existing waffle
app.put('/waffles/:id', async (req, res) => {
  const { id } = req.params;
  const { name, description, imageUrl } = req.body;
  try {
    const updatedWaffle = await prisma.waffle.update({
      where: { id: parseInt(id) },
      data: {
        name,
        description,
        imageUrl,
      },
    });
    res.json(updatedWaffle);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to update waffle' });
  }
});

// DELETE a waffle
app.delete('/waffles/:id', async (req, res) => {
  const { id } = req.params;
  try {
    await prisma.waffle.delete({
      where: { id: parseInt(id) },
    });
    res.status(204).send(); // No content
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to delete waffle' });
  }
});

// --- Server Startup ---

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

