    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error('Error fetching recipes:', error);
    return mockRecipes; // Return mock data on error
  }
}

// Function to fetch a single recipe by ID
export async function getRecipeById(id) {
  try {
    const response = await fetch(`${API_BASE_URL}/waffles/${id}`);
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error(`Error fetching recipe with ID ${id}:`, error);
    // Find the recipe in mockRecipes
    const recipe = mockRecipes.find((recipe) => recipe.id === id);
    return recipe || null; // Return the recipe if found, otherwise return null
  }
}

