import { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
import { motion } from "framer-motion";
import { ArrowLeft } from 'lucide-react';
import { getRecipeById } from "../services/api";

export default function RecipeDetail() {
  const { id } = useParams();
  const [recipe, setRecipe] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchRecipe = async () => {
      setLoading(true);
      try {
        const data = await getRecipeById(id);
        if (data) {
          setRecipe(data);
        } else {
          setError("Recipe not found.");
        }
      } catch (err) {
        setError("Failed to load recipe.");
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchRecipe();
  }, [id]);

  if (loading) {
    return <div className="p-4">Loading recipe...</div>;
  }

  if (error) {
    return (
      <div className="p-4">
        Error: {error} <Link to="/recipes">Back to Recipes</Link>
      </div>
    );
  }

  if (!recipe) {
    return (
      <div className="p-4">
        Recipe not found. <Link to="/recipes">Back to Recipes</Link>
      </div>
    );
  }

  return (
    <motion.div
      className="container mx-auto p-4 md:p-8 lg:p-12"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <Link to="/recipes" className="inline-flex items-center mb-4 text-gray-700 hover:text-gray-900">
        <ArrowLeft className="mr-2 h-5 w-5" />
        Back to Recipes
      </Link>

      <div className="bg-white/80 backdrop-blur-lg rounded-lg shadow-md overflow-hidden">
        <img
          src={recipe.image_url}
          alt={recipe.recipe_name}
          className="w-full h-64 object-cover object-center"
        />

        <div className="p-6">
          <h1 className="text-3xl font-semibold text-gray-800 mb-2">{recipe.recipe_name}</h1>
          <p className="text-gray-600 mb-4">{recipe.description}</p>

          <div className="flex items-center mb-4">
            <span className="text-sm text-gray-500 mr-2">Prep Time: {recipe.prep_time}</span>
            <span className="text-sm text-gray-500">Cook Time: {recipe.cook_time}</span>
          </div>

          <h2 className="text-xl font-semibold text-gray-800 mt-6 mb-2">Ingredients</h2>
          <ul className="list-disc list-inside text-gray-700 mb-4">
            {recipe.ingredients.map((ingredient, index) => (
              <li key={index}>{ingredient}</li>
            ))}
          </ul>

          <h2 className="text-xl font-semibold text-gray-800 mt-6 mb-2">Instructions</h2>
          <ol className="list-decimal list-inside text-gray-700">
            {recipe.instructions.map((instruction, index) => (
              <li key={index} className="mb-2">{instruction}</li>
            ))}
          </ol>
        </div>
      </div>
    </motion.div>
  );
}

