// server.js
const express = require('express');
const { PrismaClient } = require('@prisma/client');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

const prisma = new PrismaClient();
const app = express();
const port = process.env.PORT || 3000;
const secretKey = process.env.JWT_SECRET || 'secret';

app.use(express.json());

// Middleware to verify JWT token
const verifyToken = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (authHeader) {
    const token = authHeader.split(' ')[1];

    jwt.verify(token, secretKey, (err, user) => {
      if (err) {
        return res.sendStatus(403);
      }

      req.user = user;
      next();
    });
  } else {
    res.sendStatus(401);
  }
};

// Register endpoint
app.post('/register', async (req, res) => {
  try {
    const hashedPassword = await bcrypt.hash(req.body.password, 10);
    const user = await prisma.user.create({
      data: {
        username: req.body.username,
        password: hashedPassword,
      },
    });
    const token = jwt.sign({ userId: user.id }, secretKey, { expiresIn: '1h' });
    res.json({ token });
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Registration failed' });
  }
});

// Login endpoint
app.post('/login', async (req, res) => {
  try {
    const user = await prisma.user.findUnique({
      where: {
        username: req.body.username,
      },
    });

    if (user && await bcrypt.compare(req.body.password, user.password)) {
      const token = jwt.sign({ userId: user.id }, secretKey, { expiresIn: '1h' });
      res.json({ token });
    } else {
      res.status(401).json({ error: 'Invalid credentials' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Login failed' });
  }
});

// Laptop CRUD endpoints (protected)
app.get('/laptops', verifyToken, async (req, res) => {
  try {
    const laptops = await prisma.laptop.findMany();
    res.json(laptops);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch laptops' });
  }
});

app.get('/laptops/:id', verifyToken, async (req, res) => {
  try {
    const laptop = await prisma.laptop.findUnique({
      where: {
        id: parseInt(req.params.id),
      },
    });
    if (laptop) {
      res.json(laptop);
    } else {
      res.status(404).json({ error: 'Laptop not found' });
    }
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to fetch laptop' });
  }
});

app.post('/laptops', verifyToken, async (req, res) => {
  try {
    const laptop = await prisma.laptop.create({
      data: req.body,
    });
    res.status(201).json(laptop);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to create laptop' });
  }
});

app.put('/laptops/:id', verifyToken, async (req, res) => {
  try {
    const laptop = await prisma.laptop.update({
      where: {
        id: parseInt(req.params.id),
      },
      data: req.body,
    });
    res.json(laptop);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to update laptop' });
  }
});

app.delete('/laptops/:id', verifyToken, async (req, res) => {
  try {
    await prisma.laptop.delete({
      where: {
        id: parseInt(req.params.id),
      },
    });
    res.status(204).send();
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Failed to delete laptop' });
  }
});

app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});

