src/App.jsx.content:
import React, { useState, useEffect } from 'react';
import LaptopList from './components/LaptopList.jsx';
import LaptopDetails from './components/LaptopDetails.jsx';
import LaptopForm from './components/LaptopForm.jsx';
import Login from './components/Login.jsx';
import Register from './components/Register.jsx';

function App() {
  const [laptops, setLaptops] = useState([]);
  const [selectedLaptop, setSelectedLaptop] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token') || null);
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    if (token) {
      fetchLaptops();
    }
  }, [token]);

  const fetchLaptops = async () => {
    try {
      const response = await fetch('/laptops', {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      if (!response.ok) {
        throw new Error('Failed to fetch laptops');
      }
      const data = await response.json();
      setLaptops(data);
    } catch (error) {
      console.error('Error fetching laptops:', error);
    }
  };

  const handleLaptopSelect = (laptop) => {
    setSelectedLaptop(laptop);
  };

  const handleLaptopCreate = async (newLaptop) => {
    try {
      const response = await fetch('/laptops', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(newLaptop),
      });
      if (!response.ok) {
        throw new Error('Failed to create laptop');
      }
      const createdLaptop = await response.json();
      setLaptops([...laptops, createdLaptop]);
      setShowForm(false);
    } catch (error) {
      console.error('Error creating laptop:', error);
    }
  };

  const handleLaptopUpdate = async (updatedLaptop) => {
    try {
      const response = await fetch(`/laptops/${updatedLaptop.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(updatedLaptop),
      });
      if (!response.ok) {
        throw new Error('Failed to update laptop');
      }
      const updated = await response.json();
      setLaptops(laptops.map((laptop) => (laptop.id === updated.id ? updated : laptop)));
      setSelectedLaptop(updated);
    } catch (error) {
      console.error('Error updating laptop:', error);
    }
  };

  const handleLaptopDelete = async (id) => {
    try {
      const response = await fetch(`/laptops/${id}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      if (!response.ok) {
        throw new Error('Failed to delete laptop');
      }
      setLaptops(laptops.filter((laptop) => laptop.id !== id));
      setSelectedLaptop(null);
    } catch (error) {
      console.error('Error deleting laptop:', error);
    }
  };

  const handleLogin = (newToken) => {
    setToken(newToken);
    localStorage.setItem('token', newToken);
  };

  const handleLogout = () => {
    setToken(null);
    localStorage.removeItem('token');
  };

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">Laptop Store</h1>

      {!token ? (
        <div className="flex space-x-4">
          <Login onLogin={handleLogin} />
          <Register onRegister={handleLogin} />
        </div>
      ) : (
        <div>
          <button onClick={handleLogout} className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded mb-4">Logout</button>
          <button onClick={() => setShowForm(true)} className="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded mb-4">Add Laptop</button>

          {showForm && <LaptopForm onCreate={handleLaptopCreate} />}

          <LaptopList laptops={laptops} onSelect={handleLaptopSelect} />

          {selectedLaptop && (
            <LaptopDetails
              laptop={selectedLaptop}
              onUpdate={handleLaptopUpdate}
              onDelete={handleLaptopDelete}
            />
          )}
        </div>
      )}
    </div>
  );
}

export default App;

