            "display": "13.5-inch OLED Touchscreen (3000 x 2000)",
            "gpu": "Intel Iris Xe Graphics",
            "ports": ["2x Thunderbolt 4", "1x USB-A 3.2", "1x 3.5mm headphone jack"],
            "battery": "66 Whr",
            "os": "Windows 11 Home",
            "weight": "3.01 lbs",
            "price": 1499.99,
            "image_url": "https://placehold.co/400x300/2980b9/ffffff.png?text=HP+Spectre+x360",
            "description": "The HP Spectre x360 14 is a premium 2-in-1 laptop with a stunning OLED display, versatile design, and powerful performance.",
            "screen_size": 13.5,
            "touchscreen": true,
            "rating": 4.7,
            "num_reviews": 321,
            "colors": ["Nightfall Black", "Poseidon Blue"]
          }
        ];
        setLaptops(mockData);
      }
    };

    fetchLaptops();
  }, []);

  useEffect(() => {
    let results = laptops.filter(laptop =>
      laptop.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
      laptop.brand.toLowerCase().includes(searchTerm.toLowerCase())
    );

    if (sortOption === 'price-asc') {
      results = results.sort((a, b) => a.price - b.price);
    } else if (sortOption === 'price-desc') {
      results = results.sort((a, b) => b.price - a.price);
    } else if (sortOption === 'rating-desc') {
      results = results.sort((a, b) => b.rating - a.rating);
    }

    setFilteredLaptops(results);
    setCurrentPage(1); // Reset to first page on filter/sort
  }, [laptops, searchTerm, sortOption]);

  const startIndex = (currentPage - 1) * laptopsPerPage;
  const endIndex = startIndex + laptopsPerPage;
  const visibleLaptops = filteredLaptops.slice(startIndex, endIndex);

  const handleLoadMore = () => {
    setCurrentPage(currentPage + 1);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto p-6"
    >
      <div className="flex items-center justify-between mb-6">
        <div className="relative w-full md:w-1/2">
          <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
            <Search className="w-5 h-5 text-gray-500" />
          </div>
          <input
            type="search"
            placeholder="Search laptops..."
            className="block w-full p-4 pl-10 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="relative inline-block text-left">
          <div>
            <button
              type="button"
              className="inline-flex justify-center w-full px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md shadow-sm hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 dark:bg-gray-800 dark:text-gray-300 dark:border-gray-700 dark:hover:bg-gray-700"
              id="menu-button"
              aria-expanded="true"
              aria-haspopup="true"
            >
              Sort by: {
                sortOption === 'price-asc' ? 'Price (Low to High)' :
                  sortOption === 'price-desc' ? 'Price (High to Low)' :
                    'Rating (High to Low)'
              }
              <ChevronDown className="ml-2 -mr-1 h-5 w-5" aria-hidden="true" />
            </button>
          </div>

          {/* Dropdown menu (Hidden for now - needs proper implementation) */}
          {/* <div className="origin-top-right absolute right-0 mt-2 w-56 rounded-md shadow-lg bg-white ring-1 ring-black ring-opacity-5 focus:outline-none" role="menu" aria-orientation="vertical" aria-labelledby="menu-button" tabIndex="-1">
            <div className="py-1" role="none">
              <a href="#" className="text-gray-700 block px-4 py-2 text-sm hover:bg-gray-100" role="menuitem" tabIndex="-1" id="menu-item-0">Price: Low to High</a>
              <a href="#" className="text-gray-700 block px-4 py-2 text-sm hover:bg-gray-100" role="menuitem" tabIndex="-1" id="menu-item-1">Price: High to Low</a>
              <a href="#" className="text-gray-700 block px-4 py-2 text-sm hover:bg-gray-100" role="menuitem" tabIndex="-1" id="menu-item-2">Rating: High to Low</a>
            </div>
          </div> */}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
        {visibleLaptops.map(laptop => (
          <LaptopCard key={laptop.model} laptop={laptop} />
        ))}
      </div>

      {filteredLaptops.length > laptopsPerPage && endIndex < filteredLaptops.length && (
        <div className="flex justify-center mt-8">
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded"
            onClick={handleLoadMore}
          >
            Load More
          </motion.button>
        </div>
      )}
    </motion.div>
  );
}

