import React, { useState } from 'react';

function LaptopForm({ onCreate }) {
  const [newLaptop, setNewLaptop] = useState({
    brand: '',
    model: '',
    processor: '',
    ram: 0,
    storage: 0,
    price: 0,
    screen_size: 0,
    image: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewLaptop({ ...newLaptop, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onCreate(newLaptop);
    setNewLaptop({
      brand: '',
      model: '',
      processor: '',
      ram: 0,
      storage: 0,
      price: 0,
      screen_size: 0,
      image: '',
    });
  };

  return (
    <form onSubmit={handleSubmit} className="bg-white shadow-md rounded px-8 pt-6 pb-8 mb-4">
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="brand">Brand:</label>
        <input type="text" name="brand" value={newLaptop.brand} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="model">Model:</label>
        <input type="text" name="model" value={newLaptop.model} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="processor">Processor:</label>
        <input type="text" name="processor" value={newLaptop.processor} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="ram">RAM (GB):</label>
        <input type="number" name="ram" value={newLaptop.ram} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="storage">Storage (GB):</label>
        <input type="number" name="storage" value={newLaptop.storage} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="price">Price:</label>
        <input type="number" name="price" value={newLaptop.price} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="screen_size">Screen Size (inches):</label>
        <input type="number" name="screen_size" value={newLaptop.screen_size} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" />
      </div>
      <div className="mb-4">
        <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="image">Image URL:</label>
        <input type="text" name="image" value={newLaptop.image} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline" placeholder="Optional" />
      </div>
      <div className="flex items-center justify-between">
        <button className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline" type="submit">Create</button>
      </div>
    </form>
  );
}

export default LaptopForm;

