import React, { useState } from 'react';

function LaptopDetails({ laptop, onUpdate, onDelete }) {
  const [isEditing, setIsEditing] = useState(false);
  const [updatedLaptop, setUpdatedLaptop] = useState({ ...laptop });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setUpdatedLaptop({ ...updatedLaptop, [name]: value });
  };

  const handleUpdate = () => {
    onUpdate(updatedLaptop);
    setIsEditing(false);
  };

  return (
    <div className="bg-gray-100 p-4 rounded-md mt-4">
      <h2 className="text-xl font-bold mb-2">Laptop Details</h2>
      {isEditing ? (
        <div>
          <input type="text" name="brand" value={updatedLaptop.brand} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" />
          <input type="text" name="model" value={updatedLaptop.model} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" />
          <input type="text" name="processor" value={updatedLaptop.processor} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" />
          <input type="number" name="ram" value={updatedLaptop.ram} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" />
          <input type="number" name="storage" value={updatedLaptop.storage} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" />
          <input type="number" name="price" value={updatedLaptop.price} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" />
          <input type="number" name="screen_size" value={updatedLaptop.screen_size} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" />
          <input type="text" name="image" value={updatedLaptop.image || ''} onChange={handleChange} className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-2" placeholder="Image URL" />

          <button onClick={handleUpdate} className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline mr-2">Update</button>
          <button onClick={() => setIsEditing(false)} className="bg-gray-500 hover:bg-gray-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline">Cancel</button>
        </div>
      ) : (
        <div>
          <img src={laptop.image || 'https://via.placeholder.com/150'} alt={laptop.model} className="w-64 h-48 object-contain mb-2" />
          <p><strong>Brand:</strong> {laptop.brand}</p>
          <p><strong>Model:</strong> {laptop.model}</p>
          <p><strong>Processor:</strong> {laptop.processor}</p>
          <p><strong>RAM:</strong> {laptop.ram} GB</p>
          <p><strong>Storage:</strong> {laptop.storage} GB</p>
          <p><strong>Price:</strong> ${laptop.price}</p>
          <p><strong>Screen Size:</strong> {laptop.screen_size} inches</p>

          <button onClick={() => setIsEditing(true)} className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline mr-2">Edit</button>
          <button onClick={() => onDelete(laptop.id)} className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline">Delete</button>
        </div>
      )}
    </div>
  );
}

export default LaptopDetails;

