@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')
    role = data.get('role', 'student') # Default role is student

    if not username or not password:
        return jsonify({'message': 'Username and password are required'}), 400

    # Check if the username already exists
    existing_user = User.query.filter_by(username=username).first()
    if existing_user:
        return jsonify({'message': 'Username already exists'}), 400

    # Create a new user based on the role
    if role == 'student':
        new_user = Student(username=username, password=password, role=role, student_id=data.get('student_id'), name=data.get('name'), date_of_birth=data.get('date_of_birth'), email=data.get('email'))
    elif role == 'teacher':
        new_user = Teacher(username=username, password=password, role=role, teacher_id=data.get('teacher_id'), name=data.get('name'), email=data.get('email'))
    else:
        new_user = User(username=username, password=password, role=role) # Generic user (e.g., admin)

    db.session.add(new_user)
    db.session.commit()

    return jsonify({'message': 'User created successfully'}), 201


@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    user = User.query.filter_by(username=username).first()

    if user and user.password == password:  # Replace with proper password hashing in production
        # Generate a token (replace with a proper token generation library)
        token = f'{username}:{password}'  # Insecure, just for demonstration
        return jsonify({'token': token, 'message': 'Login successful'}), 200
    else:
        return jsonify({'message': 'Invalid credentials'}), 401

# --- Main ---
if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True, host='0.0.0.0', port=int(os.environ.get('PORT', 5000)))

