import { useState } from 'react';
import { motion } from 'framer-motion';
import { ChevronDown } from 'lucide-react';

const faqs = [
  {
    question: "What is a School Management System?",
    answer: "A School Management System (SMS) is a comprehensive software solution designed to streamline administrative tasks, enhance communication, and improve overall efficiency for educational institutions. It typically includes modules for student management, teacher management, course management, attendance tracking, examination management, fee management, and more."
  },
  {
    question: "What are the core features of a School Management System?",
    answer: "The core features of an SMS typically include: Student Management, Teacher Management, Course Management, Attendance Management, Examination Management, Fee Management, Communication, Library Management, Transport Management, and User Management."
  },
  {
    question: "How does a School Management System improve communication?",
    answer: "An SMS enhances communication by providing tools for announcements, email and SMS integration, a parent-teacher communication portal, and an event calendar. This ensures that all stakeholders (school, students, and parents) are well-informed and connected."
  },
  {
    question: "Is the system accessible on different devices?",
    answer: "Yes, our School Management System is designed to be responsive and accessible on various devices, including desktops, tablets, and mobile phones. This ensures that users can access the system and its features from anywhere, at any time."
  },
  {
    question: "How secure is the data stored in the School Management System?",
    answer: "Data security is a top priority. Our SMS uses role-based access control, secure user authentication and authorization, and effective password management. These measures ensure data privacy and security for all users."
  }
];

export default function FAQ() {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto p-8"
    >
      <h1 className="text-3xl font-semibold mb-8">Frequently Asked Questions</h1>
      <div className="space-y-4">
        {faqs.map((faq, index) => (
          <FAQItem key={index} question={faq.question} answer={faq.answer} />
        ))}
      </div>
    </motion.div>
  );
}

function FAQItem({ question, answer }) {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="bg-white/10 backdrop-blur-lg rounded-2xl p-4 shadow-md">
      <button
        className="flex items-center justify-between w-full text-left py-2 focus:outline-none"
        onClick={() => setIsOpen(!isOpen)}
      >
        <span className="text-lg font-semibold">{question}</span>
        <ChevronDown className={`h-6 w-6 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
      </button>
      <motion.div
        className="overflow-hidden"
        initial={{ height: 0 }}
        animate={{ height: isOpen ? 'auto' : 0 }}
        transition={{ duration: 0.3, ease: "easeInOut" }}
      >
        <div className="py-2 text-gray-700">{answer}</div>
      </motion.div>
    </div>
  );
}

