import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Search } from "lucide-react";

const mockGrades = [
  { id: 1, student: "Alice", course: "Math", grade: "A" },
  { id: 2, student: "Bob", course: "Math", grade: "B" },
  { id: 3, student: "Alice", course: "Science", grade: "A+" },
  { id: 4, student: "Charlie", course: "History", grade: "C" },
  { id: 5, student: "Bob", course: "Science", grade: "B-" },
];

export default function Grades() {
  const [grades, setGrades] = useState(mockGrades);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStudent, setFilterStudent] = useState("");
  const [filterCourse, setFilterCourse] = useState("");

  useEffect(() => {
    // Simulate API call and error handling
    const fetchGrades = async () => {
      try {
        // Replace with actual API call
        // const response = await fetch('/api/grades');
        // const data = await response.json();
        // setGrades(data);
      } catch (error) {
        console.error("Error fetching grades:", error);
        // Fallback to mock data
        setGrades(mockGrades);
      }
    };

    fetchGrades();
  }, []);

  const filteredGrades = grades.filter((grade) => {
    const searchMatch =
      grade.student.toLowerCase().includes(searchTerm.toLowerCase()) ||
      grade.course.toLowerCase().includes(searchTerm.toLowerCase());
    const studentMatch = filterStudent ? grade.student === filterStudent : true;
    const courseMatch = filterCourse ? grade.course === filterCourse : true;
    return searchMatch && studentMatch && courseMatch;
  });

  const uniqueStudents = [...new Set(grades.map((grade) => grade.student))];
  const uniqueCourses = [...new Set(grades.map((grade) => grade.course))];

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto p-8"
    >
      <h1 className="text-3xl font-semibold mb-4">Grades</h1>

      <div className="mb-4 flex space-x-2">
        <div className="relative flex-grow">
          <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
            <Search className="h-5 w-5 text-gray-500" />
          </div>
          <input
            type="search"
            placeholder="Search students or courses..."
            className="block w-full p-2 pl-10 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <select
          className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
          value={filterStudent}
          onChange={(e) => setFilterStudent(e.target.value)}
        >
          <option value="">All Students</option>
          {uniqueStudents.map((student) => (
            <option key={student} value={student}>
              {student}
            </option>
          ))}
        </select>

        <select
          className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg focus:ring-blue-500 focus:border-blue-500 block w-full p-2.5 dark:bg-gray-700 dark:border-gray-600 dark:placeholder-gray-400 dark:text-white dark:focus:ring-blue-500 dark:focus:border-blue-500"
          value={filterCourse}
          onChange={(e) => setFilterCourse(e.target.value)}
        >
          <option value="">All Courses</option>
          {uniqueCourses.map((course) => (
            <option key={course} value={course}>
              {course}
            </option>
          ))}
        </select>
      </div>

      <div className="overflow-x-auto">
        <table className="min-w-full leading-normal">
          <thead>
            <tr>
              <th className="px-5 py-3 border-b-2 border-gray-200 bg-gray-100 text-left text-xs font-semibold text-gray-600 uppercase tracking-wider">
