import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Search } from "lucide-react";
import CourseCard from "../components/CourseCard";
import { getAllCourses } from "../services/courses";

const mockCourses = [
  {
    course_id: 1,
    course_name: "Introduction to React",
    description: "Learn the basics of React development.",
    credit_hours: 3,
  },
  {
    course_id: 2,
    course_name: "Advanced JavaScript",
    description: "Deep dive into advanced JavaScript concepts.",
    credit_hours: 4,
  },
  {
    course_id: 3,
    course_name: "Data Structures and Algorithms",
    description: "Master essential data structures and algorithms.",
    credit_hours: 4,
  },
];

export default function Courses() {
  const [courses, setCourses] = useState(mockCourses);
  const [searchTerm, setSearchTerm] = useState("");
  const [filteredCourses, setFilteredCourses] = useState(mockCourses);

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const data = await getAllCourses();
        setCourses(data);
        setFilteredCourses(data);
      } catch (error) {
        console.error("Error fetching courses:", error);
        // Fallback to mock data
        setCourses(mockCourses);
        setFilteredCourses(mockCourses);
      }
    };

    fetchCourses();
  }, []);

  useEffect(() => {
    const results = courses.filter((course) =>
      course.course_name.toLowerCase().includes(searchTerm.toLowerCase())
    );
    setFilteredCourses(results);
  }, [searchTerm, courses]);

  const handleSearchChange = (event) => {
    setSearchTerm(event.target.value);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto p-8"
    >
      <h1 className="text-3xl font-semibold mb-4">Courses</h1>

      <div className="mb-4 flex items-center">
        <div className="relative w-full">
          <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
            <Search className="h-5 w-5 text-gray-500" />
          </div>
          <input
            type="search"
            placeholder="Search for courses..."
            className="block w-full p-4 pl-10 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-blue-500 focus:border-blue-500 focus:outline-none"
            value={searchTerm}
            onChange={handleSearchChange}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredCourses.map((course) => (
          <CourseCard key={course.course_id} course={course} />
        ))}
      </div>
    </motion.div>
