  useEffect(() => {
    // Apply sorting
    let sortedData = [...attendanceData];
    if (sortOrder === "name-asc") {
      sortedData.sort((a, b) => a.studentName.localeCompare(b.studentName));
    } else if (sortOrder === "name-desc") {
      sortedData.sort((a, b) => b.studentName.localeCompare(a.studentName));
    } else if (sortOrder === "date-asc") {
      sortedData.sort((a, b) => new Date(a.date) - new Date(b.date));
    } else if (sortOrder === "date-desc") {
      sortedData.sort((a, b) => new Date(b.date) - new Date(a.date));
    }

    // Apply filtering
    let filteredData = [...sortedData];
    if (filterStatus !== "all") {
      filteredData = filteredData.filter((item) => item.status.toLowerCase() === filterStatus);
    }

    setAttendanceData(filteredData);
  }, [sortOrder, filterStatus]);

  const handleSortChange = (e) => {
    const newSortOrder = e.target.value;
    setSortOrder(newSortOrder);
    searchParams.set("sort", newSortOrder);
    setSearchParams(searchParams);
  };

  const handleFilterChange = (e) => {
    const newFilterStatus = e.target.value;
    setFilterStatus(newFilterStatus);
    searchParams.set("filter", newFilterStatus);
    setSearchParams(searchParams);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto p-8"
    >
      <h2 className="text-2xl font-semibold mb-4">Attendance Records</h2>

      {/* Sorting and Filtering Controls */}
      <div className="flex flex-wrap gap-4 mb-4">
        {/* Sort Select */}
        <div>
          <label htmlFor="sort" className="block text-sm font-medium text-gray-700">
            Sort By:
          </label>
          <div className="relative">
            <select
              id="sort"
              className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md"
              value={sortOrder}
              onChange={handleSortChange}
            >
              {sortOptions.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
            <div className="absolute inset-y-0 right-0 flex items-center pointer-events-none">
              <ChevronDown className="h-5 w-5 text-gray-400" aria-hidden="true" />
            </div>
          </div>
        </div>

        {/* Filter Select */}
        <div>
          <label htmlFor="filter" className="block text-sm font-medium text-gray-700">
            Filter By:
          </label>
          <div className="relative">
            <select
              id="filter"
              className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-primary focus:border-primary sm:text-sm rounded-md"
              value={filterStatus}
              onChange={handleFilterChange}
            >
              {filterOptions.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
            <div className="absolute inset-y-0 right-0 flex items-center pointer-events-none">
              <ChevronDown className="h-5 w-5 text-gray-400" aria-hidden="true" />
            </div>
          </div>
        </div>
      </div>

      {/* Attendance Table */}
      <div className="overflow-x-auto">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th
                scope="col"
                className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
              >
                Student Name
              </th>
              <th
                scope="col"
                className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
              >
                Date
              </th>
              <th
                scope="col"
                className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"
              >
                Status
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {attendanceData.map((item) => (
              <tr key={item.id}>
                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                  {item.studentName}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{item.date}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{item.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </motion.div>
  );
}

