// src/services/pos.js

const API_BASE_URL = '/api'; // Or your actual API base URL

async function getProducts() {
  try {
    const response = await fetch(`${API_BASE_URL}/products`);
    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error("Error fetching products:", error);
    throw error; // Re-throw to allow components to handle
  }
}

async function getCategories() {
  try {
    const response = await fetch(`${API_BASE_URL}/categories`);
    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error("Error fetching categories:", error);
    throw error;
  }
}

async function processTransaction(transactionData) {
    try {
      const response = await fetch(`${API_BASE_URL}/transactions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(transactionData),
      });

      if (!response.ok) {
        // Attempt to parse the error message from the response
        let errorMessage = `Transaction failed with status: ${response.status}`;
        try {
          const errorData = await response.json();
          errorMessage = errorData.message || errorMessage; // Use the message from the server if available
        } catch (parseError) {
          console.error("Failed to parse error message from response:", parseError);
          // If parsing fails, we keep the original error message
        }

        throw new Error(errorMessage);
      }

      const data = await response.json();
      return data;
    } catch (error) {
      console.error("Error processing transaction:", error);
      throw error; // Re-throw the error for the component to handle
    }
  }

export { getProducts, getCategories, processTransaction };

