src/components/CashierFlow.jsx.content:
import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { X, Search, ChevronDown, ArrowRight, Check, AlertCircle } from 'lucide-react';
import { clsx } from "clsx";
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const productsData = [
    { id: 1, name: "Coffee", price: 3.50, image: "assets/coffee.png" },
    { id: 2, name: "Sandwich", price: 7.00, image: "assets/sandwich.png" },
    { id: 3, name: "Donut", price: 2.00, image: "https://placehold.co/800x600/2980b9/ffffff.png?text=Donut" },
    { id: 4, name: "Juice", price: 4.00, image: "https://placehold.co/800x600/2980b9/ffffff.png?text=Juice" },
    { id: 5, name: "Salad", price: 8.00, image: "https://placehold.co/800x600/2980b9/ffffff.png?text=Salad" },
    { id: 6, name: "Water Bottle", price: 1.50, image: "https://placehold.co/800x600/2980b9/ffffff.png?text=Water" },
];

export default function CashierFlow() {
    const [products, setProducts] = useState(productsData);
    const [cart, setCart] = useState([]);
    const [searchTerm, setSearchTerm] = useState("");
    const [paymentProcessing, setPaymentProcessing] = useState(false);
    const [paymentMethod, setPaymentMethod] = useState("cash"); // Default payment method
    const [paymentAmount, setPaymentAmount] = useState("");
    const [paymentSuccess, setPaymentSuccess] = useState(false);

    const filteredProducts = products.filter(product =>
        product.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const addToCart = (product) => {
        const existingItem = cart.find(item => item.id === product.id);
        if (existingItem) {
            const updatedCart = cart.map(item =>
                item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
            );
            setCart(updatedCart);
        } else {
            setCart([...cart, { ...product, quantity: 1 }]);
        }
    };

    const removeFromCart = (productId) => {
        const updatedCart = cart.filter(item => item.id !== productId);
        setCart(updatedCart);
    };

    const adjustQuantity = (productId, newQuantity) => {
        if (newQuantity < 1) {
            removeFromCart(productId);
            return;
        }
        const updatedCart = cart.map(item =>
            item.id === productId ? { ...item, quantity: newQuantity } : item
        );
        setCart(updatedCart);
    };

    const calculateTotal = () => {
        return cart.reduce((total, item) => total + item.price * item.quantity, 0).toFixed(2);
    };

    const handlePayment = () => {
        if (cart.length === 0) {
            toast.error("Cart is empty. Please add items to the cart.", { position: "top-center" });
            return;
        }

        if (paymentAmount === "" || isNaN(paymentAmount) || parseFloat(paymentAmount) <= 0) {
            toast.error("Please enter a valid payment amount.", { position: "top-center" });
            return;
        }

        if (parseFloat(paymentAmount) < parseFloat(calculateTotal())) {
            toast.error("Payment amount is less than the total amount.", { position: "top-center" });
            return;
        }

        setPaymentProcessing(true);

        // Simulate payment processing delay
        setTimeout(() => {
            setPaymentProcessing(false);
            setPaymentSuccess(true);
            setCart([]); // Clear the cart after successful payment
            setPaymentAmount(""); // Reset payment amount
            toast.success("Payment successful!", { position: "top-center" });
        }, 2000);
    };


    const handleClosePayment = () => {
        setPaymentProcessing(false);
    };

    return (
        <div className="container mx-auto p-4">
            <motion.h1
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5 }}
                className="text-2xl font-semibold mb-4 text-gray-800"
            >
                Cashier Flow
            </motion.h1>

            {/* Search Bar */}
            <div className="mb-4 flex items-center">
                <div className="relative w-full">
                    <input
                        type="text"
                        placeholder="Search products..."
                        className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-300 focus:ring-2 ring-primary focus:outline-none"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className="h-5 w-5 text-gray-400" />
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-4">
                {filteredProducts.map(product => (
                    <motion.div
                        key={product.id}
                        className="bg-white rounded-2xl shadow-md overflow-hidden flex flex-col"
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                    >
                        <img src={product.image} alt={product.name} className="object-cover h-48 w-full" />
                        <div className="p-4 flex flex-col justify-between flex-grow">
                            <div>
                                <h3 className="text-lg font-semibold text-gray-800">{product.name}</h3>
                                <p className="text-gray-600">${product.price.toFixed(2)}</p>
                            </div>
                            <button
                                className="mt-2 bg-primary text-white py-2 px-4 rounded-lg hover:bg-primary-dark focus:outline-none focus:ring-2 ring-primary"
                                onClick={() => addToCart(product)}
                            >
                                Add to Cart
                            </button>
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Cart */}
            <div className="bg-white rounded-2xl shadow-md p-4">
                <h2 className="text-xl font-semibold mb-2 text-gray-800">Shopping Cart</h2>
                {cart.length === 0 ? (
                    <p className="text-gray-500">Your cart is empty.</p>
                ) : (
                    <div>
                        {cart.map(item => (
                            <div key={item.id} className="flex items-center justify-between py-2 border-b border-gray-200">
                                <div className="flex items-center">
                                    <img src={item.image} alt={item.name} className="w-12 h-12 object-cover rounded-lg mr-2" />
                                    <div>
                                        <h3 className="text-gray-800 font-semibold">{item.name}</h3>
                                        <p className="text-gray-600">${item.price.toFixed(2)}</p>
                                    </div>
                                </div>
                                <div className="flex items-center">
                                    <button
                                        className="bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold py-1 px-3 rounded-l"
                                        onClick={() => adjustQuantity(item.id, item.quantity - 1)}
                                    >
                                        -
                                    </button>
                                    <input
                                        type="number"
                                        className="w-16 text-center py-1 border-none focus:ring-0 focus:outline-none"
                                        value={item.quantity}
                                        onChange={(e) => {
                                            const newQuantity = parseInt(e.target.value);
                                            adjustQuantity(item.id, newQuantity);
                                        }}
                                    />
                                    <button
                                        className="bg-gray-200 hover:bg-gray-300 text-gray-700 font-bold py-1 px-3 rounded-r"
                                        onClick={() => adjustQuantity(item.id, item.quantity + 1)}
                                    >
                                        +
                                    </button>
                                    <button
                                        className="ml-2 text-red-500 hover:text-red-700 focus:outline-none"
                                        onClick={() => removeFromCart(item.id)}
                                    >
                                        <X className="h-5 w-5" />
                                    </button>
                                </div>
                            </div>
                        ))}
                        <div className="mt-4 flex justify-between items-center">
                            <span className="text-lg font-semibold text-gray-800">Total:</span>
                            <span className="text-xl font-bold text-gray-900">${calculateTotal()}</span>
                        </div>
                    </div>
                )}
            </div>

            {/* Payment Section */}
            <motion.div
                className="mt-4"
                initial={{ opacity: 0 }}
                animate={{ opacity: cart.length > 0 ? 1 : 0 }}
                transition={{ duration: 0.3 }}
            >
                {cart.length > 0 && (
                    <button
                        className="bg-green-500 text-white py-3 px-6 rounded-lg hover:bg-green-600 focus:outline-none focus:ring-2 ring-green-400"
                        onClick={() => setPaymentProcessing(true)}
                    >
                        Proceed to Payment
                    </button>
                )}
            </motion.div>

            {/* Payment Processing Overlay */}
            {paymentProcessing && (
                <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="fixed top-0 left-0 w-full h-full bg-black/50 backdrop-blur-lg flex items-center justify-center"
                >
                    <div className="bg-white rounded-2xl shadow-lg p-8 max-w-md w-full">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-xl font-semibold text-gray-800">Payment Processing</h2>
                            <button onClick={handleClosePayment} className="text-gray-500 hover:text-gray-700 focus:outline-none">
                                <X className="h-6 w-6" />
                            </button>
                        </div>

                        {/* Payment Method Selection */}
                        <div className="mb-4">
                            <label htmlFor="paymentMethod" className="block text-gray-700 text-sm font-bold mb-2">
                                Payment Method:
                            </label>
                            <select
                                id="paymentMethod"
                                className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                                value={paymentMethod}
                                onChange={(e) => setPaymentMethod(e.target.value)}
                            >
                                <option value="cash">Cash</option>
                                <option value="creditCard">Credit Card</option>
                                <option value="mobilePayment">Mobile Payment</option>
                            </select>
                        </div>

                        {/* Payment Amount Input */}
                        <div className="mb-4">
                            <label htmlFor="paymentAmount" className="block text-gray-700 text-sm font-bold mb-2">
                                Amount Tendered:
                            </label>
                            <input
                                type="number"
                                id="paymentAmount"
                                className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                                placeholder="Enter amount"
                                value={paymentAmount}
                                onChange={(e) => setPaymentAmount(e.target.value)}
                            />
                        </div>

                        <button
                            className="bg-blue-500 text-white py-2 px-4 rounded-lg hover:bg-blue-600 focus:outline-none focus:ring-2 ring-blue-400 w-full"
                            onClick={handlePayment}
                        >
                            Process Payment
                        </button>
                    </div>
                </motion.div>
            )}
        </div>
    );
}

