    category: "Berry",
    price: 4.0,
    image: "assets/blueberry.png",
    description: "Healthy and antioxidant-rich blueberries.",
    nutrition: {
      calories: 84,
      fiber: 4,
      vitamin_c: 24,
    },
  },
];

export default function Shop() {
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("All");
  const [sortOption, setSortOption] = useState("Price: Low to High");
  const [fruits, setFruits] = useState(mockFruits);

  useEffect(() => {
    let filteredFruits = mockFruits;

    if (categoryFilter !== "All") {
      filteredFruits = filteredFruits.filter(
        (fruit) => fruit.category === categoryFilter
      );
    }

    if (searchTerm) {
      filteredFruits = filteredFruits.filter((fruit) =>
        fruit.name.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    let sortedFruits = [...filteredFruits]; // Create a copy to avoid mutating the original

    if (sortOption === "Price: Low to High") {
      sortedFruits.sort((a, b) => a.price - b.price);
    } else if (sortOption === "Price: High to Low") {
      sortedFruits.sort((a, b) => b.price - a.price);
    } else if (sortOption === "Name: A to Z") {
      sortedFruits.sort((a, b) => a.name.localeCompare(b.name));
    }

    setFruits(sortedFruits);
  }, [searchTerm, categoryFilter, sortOption]);

  const categories = ["All", "Fruit", "Berry"];

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto px-4 py-8"
    >
