            <Link to="/shop" className="text-lg hover:text-primary focus:outline-none focus:ring-2 ring-primary" onClick={toggleMenu}>Products</Link>
            <Link to="/about" className="text-lg hover:text-primary focus:outline-none focus:ring-2 ring-primary" onClick={toggleMenu}>About</Link>
            <Link to="/contact" className="text-lg hover:text-primary focus:outline-none focus:ring-2 ring-primary" onClick={toggleMenu}>Contact</Link>
