import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";
import { Search, Filter, SortAsc, SortDesc } from "lucide-react";
import ProductCard from "../components/ProductCard";

const mockProducts = [
  {
    id: 1,
    name: "Serpent Earcuff",
    imageUrl: "/assets/serpent_earcuff.png",
    price: 49.99,
    description: "A bold serpent design for an edgy look.",
    style: "Statement",
    material: "Sterling Silver",
  },
  {
    id: 2,
    name: "Celestial Earcuff",
    imageUrl: "/assets/celestial_earcuff.png",
    price: 59.99,
    description: "Inspired by the stars, a celestial design.",
    style: "Minimalist",
    material: "Gold Plated",
  },
  {
    id: 3,
    name: "Minimalist Earcuff",
    imageUrl: "/assets/minimalist_earcuff.png",
    price: 39.99,
    description: "Simple and elegant for everyday wear.",
    style: "Minimalist",
    material: "Sterling Silver",
  },
  {
    id: 4,
    name: "Gothic Earcuff",
    imageUrl: "/assets/gothic_earcuff.png",
    price: 69.99,
    description: "Dark and mysterious, a gothic-inspired design.",
    style: "Statement",
    material: "Stainless Steel",
  },
  {
    id: 5,
    name: "Boho Earcuff",
    imageUrl: "/assets/boho_earcuff.png",
    price: 44.99,
    description: "Free-spirited and bohemian, perfect for any outfit.",
    style: "Boho",
    material: "Brass",
  },
  {
    id: 6,
    name: "Diamond Earcuff",
    imageUrl: "/assets/diamond_earcuff.png",
    price: 99.99,
    description: "Sparkling diamonds for a touch of luxury.",
    style: "Luxury",
    material: "White Gold",
  },
];

export default function Shop() {
  const [products, setProducts] = useState(mockProducts);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterStyle, setFilterStyle] = useState("All");
  const [sortBy, setSortBy] = useState("Price (Low to High)");

  useEffect(() => {
    let filteredProducts = mockProducts;

    if (searchTerm) {
      filteredProducts = filteredProducts.filter((product) =>
        product.name.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    if (filterStyle !== "All") {
      filteredProducts = filteredProducts.filter(
        (product) => product.style === filterStyle
      );
    }

    if (sortBy === "Price (Low to High)") {
      filteredProducts = [...filteredProducts].sort((a, b) => a.price - b.price);
    } else if (sortBy === "Price (High to Low)") {
      filteredProducts = [...filteredProducts].sort((a, b) => b.price - a.price);
    }

    setProducts(filteredProducts);
  }, [searchTerm, filterStyle, sortBy]);

  const handleSearchChange = (e) => {
    setSearchTerm(e.target.value);
  };

  const handleFilterChange = (e) => {
    setFilterStyle(e.target.value);
  };

  const handleSortChange = (e) => {
    setSortBy(e.target.value);
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="container mx-auto py-12 px-4 sm:px-6 lg:px-8"
    >
      <div className="md:flex md:items-center md:justify-between mb-8">
        <div className="mb-4 md:mb-0">
          <h1 className="text-2xl font-bold text-gray-900">Shop Earcuffs</h1>
        </div>

        <div className="flex flex-col md:flex-row items-center gap-4">
          <div className="relative w-full md:w-64">
            <div className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
              <Search className="h-5 w-5 text-gray-400" />
            </div>
            <input
              type="search"
              placeholder="Search products..."
              value={searchTerm}
              onChange={handleSearchChange}
              className="block w-full p-2 pl-10 text-sm text-gray-900 border border-gray-300 rounded-lg bg-gray-50 focus:ring-primary focus:border-primary focus:outline-none"
            />
          </div>

          <div className="flex items-center gap-2">
            <div className="relative">
              <select
                value={filterStyle}
                onChange={handleFilterChange}
                className="block appearance-none w-full bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg py-2 px-4 pr-8 leading-tight focus:outline-none focus:bg-white focus:border-primary"
              >
                <option value="All">All Styles</option>
                <option value="Minimalist">Minimalist</option>
                <option value="Statement">Statement</option>
                <option value="Boho">Boho</option>
              </select>
              <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
                <Filter className="h-5 w-5" />
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <div className="relative">
              <select
                value={sortBy}
                onChange={handleSortChange}
                className="block appearance-none w-full bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg py-2 px-4 pr-8 leading-tight focus:outline-none focus:bg-white focus:border-primary"
              >
                <option value="Price (Low to High)">Price (Low to High)</option>
                <option value="Price (High to Low)">Price (High to Low)</option>
              </select>
              <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-700">
                {sortBy === "Price (Low to High)" ? (
                  <SortAsc className="h-5 w-5" />
                ) : (
                  <SortDesc className="h-5 w-5" />
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {products.map((product) => (
          <ProductCard key={product.id} {...product} />
        ))}
      </div>

      {products.length === 0 && (
        <div className="text-center mt-8">
          <p className="text-gray-500">No products found matching your criteria.</p>
        </div>
      )}
    </motion.div>
  );
}

