:root {
    --primary-color: #1E293B; /* Dark Blue Gray */
    --secondary-color: #3B82F6; /* Softer Blue */
    --accent-color: #60A5FA; /* Light Blue */
    --text-color: #334155; /* Darker Gray for Text */
    --background-color: #F9FAFB; /* Very Light Gray */
    --glass-bg: rgba(255, 255, 255, 0.2); /* White Glassmorphism */
    --glass-border: rgba(255, 255, 255, 0.3);
    --glass-shadow: rgba(0, 0, 0, 0.1);
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background-color: var(--background-color);
    color: var(--text-color);
    margin: 0;
    padding: 0;
}

/* Basic Styling for Reusable Components */
.container {
    width: 90%;
    max-width: 1200px;
    margin: 0 auto;
}

/* Header Styles */
header {
    background-color: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    padding: 1rem 0;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 100;
}

header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

header a {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 600;
    transition: color 0.3s ease;
}

header a:hover {
    color: var(--secondary-color);
}

/* Active Link Style */
header a.active-link {
    color: var(--secondary-color);
}

/* Mobile Menu Button */
#mobile-menu-button {
    background: none;
    border: none;
    color: var(--primary-color);
    cursor: pointer;
    font-size: 1.2rem;
    padding: 0.5rem;
    transition: color 0.3s ease;
}

#mobile-menu-button:hover {
    color: var(--accent-color);
}

/* Mobile Menu Styles */
#mobile-menu {
    position: absolute;
    top: 100%;
    left: 0;
    width: 100%;
    background-color: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(10px);
    padding: 1rem;
    display: none; /* Hidden by default, toggled by JavaScript */
    flex-direction: column;
    align-items: center;
    gap: 1rem;
    z-index: 99;
}

#mobile-menu a {
    color: var(--primary-color);
    text-decoration: none;
    font-weight: 600;
    font-size: 1.1rem;
    transition: color 0.3s ease;
}

#mobile-menu a:hover {
    color: var(--secondary-color);
}

/* Footer Styles */
footer {
    background-color: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
    padding: 2rem 0;
    text-align: center;
    color: var(--text-color);
    position: sticky;
    bottom: 0;
    width: 100%;
}

footer .container {
    border-top: 1px solid rgba(0, 0, 0, 0.1);
    padding-top: 1rem;
}

footer ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    justify-content: center;
    gap: 1rem;
}

footer a {
    color: var(--text-color);
    text-decoration: none;
    transition: color 0.3s ease;
}

footer a:hover {
    color: var(--secondary-color);
}

/* Utility Classes (can be expanded as needed) */
.hidden {
    display: none;
}

/* Glassmorphism effect */
.glassmorphism {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow: 0 8px 32px 0 var(--glass-shadow);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-radius: 10px;
    padding: 15px;
}

.reveal {
  position: relative;
  transform: translateY(150px);
  opacity: 0;
  transition: 1s all ease;
}

.reveal.revealed {
  transform: translateY(0);
  opacity: 1;
}

