import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";
import { ArrowRight } from "lucide-react";

export default function Home() {
  const [articles, setArticles] = useState([
    {
      id: 1,
      title: "The Future of Web Design",
      excerpt:
        "Explore the latest trends in web design and how they're shaping the future of the internet.",
      imageUrl: "assets/article1.jpg",
    },
    {
      id: 2,
      title: "Mastering React Hooks",
      excerpt:
        "Learn how to leverage React hooks to build more efficient and maintainable components.",
      imageUrl: "assets/article2.jpg",
    },
    {
      id: 3,
      title: "Tailwind CSS: A Comprehensive Guide",
      excerpt:
        "Discover the power of Tailwind CSS and how it can streamline your styling workflow.",
      imageUrl: "assets/article3.jpg",
    },
  ]);

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("revealed");
        } else {
          entry.target.classList.remove("revealed");
        }
      });
    });

    const reveals = document.querySelectorAll(".reveal");
    reveals.forEach((reveal) => observer.observe(reveal));

    return () => {
      reveals.forEach((reveal) => observer.unobserve(reveal));
    };
  }, []);

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="bg-white text-black min-h-screen flex flex-col"
    >
      {/* Hero Section */}
      <section className="py-24 px-6 md:px-12 lg:px-24 flex flex-col items-center justify-center">
        <h1 className="text-5xl md:text-6xl lg:text-7xl font-bold text-center mb-4 reveal">Hello.</h1>
        <p className="text-lg md:text-xl lg:text-2xl text-center mb-8 reveal" style={{ transitionDelay: '0.2s' }}>
          Welcome to a new era of digital experiences. Crafted with precision,
          engineered for speed.
        </p>
        <div className="flex space-x-4 reveal" style={{ transitionDelay: '0.4s' }}>
          <Link
            to="/services"
            className="btn btn-primary"
          >
            Explore Our Services
          </Link>
          <Link
            to="/contact"
            className="btn btn-secondary"
          >
            Contact Us
          </Link>
        </div>
      </section>

      {/* Article List */}
      <section className="py-12 px-6 md:px-12 lg:px-24">
        <h2 className="text-3xl font-semibold mb-6 reveal">Featured Articles</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {articles.map((article, index) => (
            <motion.div
              key={article.id}
              className="glassmorphism overflow-hidden hover:scale-105 transition-transform reveal"
              style={{ transitionDelay: `${0.1 * index + 0.5}s` }}
              whileHover={{ y: -5 }}
            >
              <img
                src={article.imageUrl}
                alt={article.title}
                className="object-cover h-48 w-full"
              />
              <div className="p-4">
                <h3 className="text-xl font-semibold mb-2 text-primary">{article.title}</h3>
                <p className="text-gray-700 mb-4">{article.excerpt}</p>
                <Link
                  to={`/article/${article.id}`}
                  className="text-black hover:text-gray-800 flex items-center space-x-2"
                >
                  <span>Read More</span>
                  <ArrowRight className="h-5 w-5" />
                </Link>
              </div>
            </motion.div>
          ))}
        </div>
      </section>
    </motion.div>
  );
}

