import { useState, useEffect } from 'react';
import { NavLink } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { motion } from 'framer-motion';

export default function Header() {
  const [isOpen, setIsOpen] = useState(false);
  const [isSticky, setIsSticky] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsSticky(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);

    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const toggleMenu = () => {
    setIsOpen(!isOpen);
  };

  return (
    <motion.header
      className={`fixed top-0 left-0 w-full z-50 ${isSticky ? 'bg-white/10 backdrop-blur-lg shadow-md' : 'bg-transparent'} py-4 px-6 transition-all duration-300`}
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.7, delay: 0.2, ease: "cubic-bezier(0.4, 0, 0.2, 1)" }}
    >
      <div className="container mx-auto flex items-center justify-between">
        <NavLink to="/" className="text-xl font-bold text-primary">
          Minimalist
        </NavLink>

        {/* Mobile Menu Button */}
        <button
          onClick={toggleMenu}
          className="md:hidden text-primary focus:outline-none"
        >
          {isOpen ? <X size={24} /> : <Menu size={24} />}
        </button>

        {/* Desktop Navigation */}
        <nav className="hidden md:flex space-x-6">
          <NavLink to="/" className={({ isActive }) => `text-primary hover:text-secondary ${isActive ? 'active-link' : ''}`}>
            Home
          </NavLink>
          <NavLink to="/about" className={({ isActive }) => `text-primary hover:text-secondary ${isActive ? 'active-link' : ''}`}>
            About
          </NavLink>
          <NavLink to="/services" className={({ isActive }) => `text-primary hover:text-secondary ${isActive ? 'active-link' : ''}`}>
            Services
          </NavLink>
          <NavLink to="/contact" className={({ isActive }) => `text-primary hover:text-secondary ${isActive ? 'active-link' : ''}`}>
            Contact
          </NavLink>
        </nav>

        {/* Mobile Navigation (Conditional Rendering) */}
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.4, ease: "cubic-bezier(0.4, 0, 0.2, 1)" }}
            className="md:hidden absolute top-full left-0 w-full bg-white/10 backdrop-blur-lg py-4 flex flex-col items-center space-y-4"
          >
            <NavLink to="/" className="text-primary hover:text-secondary block" onClick={toggleMenu}>
              Home
            </NavLink>
            <NavLink to="/about" className="text-primary hover:text-secondary block" onClick={toggleMenu}>
              About
            </NavLink>
            <NavLink to="/services" className="text-primary hover:text-secondary block" onClick={toggleMenu}>
              Services
            </NavLink>
            <NavLink to="/contact" className="text-primary hover:text-secondary block" onClick={toggleMenu}>
              Contact
            </NavLink>
          </motion.div>
        )}
      </div>
    </motion.header>
  );
}

script.js.content:
document.addEventListener('DOMContentLoaded', function() {
    // Mobile Menu Toggle
    const mobileMenuButton = document.getElementById('mobile-menu-button');
    const mobileMenu = document.getElementById('mobile-menu');

    if (mobileMenuButton && mobileMenu) {
        mobileMenuButton.addEventListener('click', function() {
            mobileMenu.classList.toggle('hidden');
        });
    }

    // Reveal on Scroll
    const reveals = document.querySelectorAll('.reveal');

    const observer = new IntersectionObserver(entries => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('active');
                observer.unobserve(entry.target); // Stop observing after revealing
            }
        });
    }, { threshold: 0.2 }); // Adjust threshold as needed

    reveals.forEach(reveal => {
        observer.observe(reveal);
    });

    // Back to Top Button
    const backToTopButton = document.createElement('button');
    backToTopButton.id = 'back-to-top';
    backToTopButton.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="w-6 h-6"><path stroke-linecap="round" stroke-linejoin="round" d="M4.5 15.75l7.5-7.5 7.5 7.5" /></svg>'; // Up arrow icon
    backToTopButton.classList.add('fixed', 'bottom-4', 'right-4', 'bg-primary', 'text-white', 'rounded-full', 'p-2', 'opacity-0', 'transition-opacity', 'duration-300', 'ease-in-out', 'focus:outline-none', 'focus:ring-2', 'ring-white');
    backToTopButton.style.zIndex = '50'; // Ensure it's above other elements
    document.body.appendChild(backToTopButton);

    window.addEventListener('scroll', function() {
        if (window.scrollY > 1000) {
            backToTopButton.classList.remove('opacity-0');
            backToTopButton.classList.add('opacity-100');
        } else {
            backToTopButton.classList.remove('opacity-100');
            backToTopButton.classList.add('opacity-0');
        }
    });

    backToTopButton.addEventListener('click', function(e) {
        e.preventDefault();
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    });
});

style.css.content:
/* style.css */

@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;700&family=Open+Sans:wght@400;600&display=swap');

:root {
  /* Primary Colors */
  --primary-color: #2E9AFE;
  --secondary-color: #FFFFFF;
  --background-color: #17202A;

  /* Typography */
  --primary-font: 'Roboto', sans-serif;
  --secondary-font: 'Open Sans', sans-serif;

  /* Glassmorphism */
  --glass-bg: rgba(255, 255, 255, 0.1);
  --glass-border: rgba(255, 255, 255, 0.2);
  --glass-backdrop-blur: blur(10px); /* Adjust as needed */
}

body {
  font-family: var(--secondary-font);
  background-color: var(--background-color);
  color: var(--secondary-color);
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

/* Basic Reset */
html, body, div, span, applet, object, iframe,
h1, h2, h3, h4, h5, h6, p, blockquote, pre,
a, abbr, acronym, address, big, cite, code,
del, dfn, em, img, ins, kbd, q, s, samp,
small, strike, strong, sub, sup, tt, var,
b, u, i, center,
dl, dt, dd, ol, ul, li,
fieldset, form, label, legend,
table, caption, tbody, tfoot, thead, tr, th, td,
article, aside, canvas, details, embed,
figure, figcaption, footer, header, hgroup,
menu, nav, output, ruby, section, summary,
time, mark, audio, video {
  margin: 0;
  padding: 0;
  border: 0;
  font-size: 100%;
  font: inherit;
  vertical-align: baseline;
}

/* HTML5 display-role reset for older browsers */
article, aside, details, figcaption, figure,
footer, header, hgroup, menu, nav, section {
  display: block;
}

ol, ul {
  list-style: none;
}

blockquote, q {
  quotes: none;
}

blockquote:before, blockquote:after,
q:before, q:after {
  content: '';
  content: none;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
}

/* Typography */
h1, h2, h3 {
  font-family: var(--primary-font);
  font-weight: 700;
  color: var(--primary-color);
  line-height: 1.2;
  margin-bottom: 0.5em;
}

h1 {
  font-size: clamp(2.5rem, 5vw, 4rem);
}

h2 {
  font-size: clamp(2rem, 4vw, 3rem);
}

h3 {
  font-size: clamp(1.5rem, 3vw, 2rem);
}

p {
  font-size: 1rem;
  line-height: 1.6;
  margin-bottom: 1em;
}

a {
  color: var(--primary-color);
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover {
  color: lighten(var(--primary-color), 10%);
}

/* Glassmorphism Card */
.glass-card {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  backdrop-filter: var(--glass-backdrop-blur);
  border-radius: 1rem;
  padding: 1.5rem;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

/* Spacing System (Fluid) */
.container {
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem;
}

/* Responsive Utilities */
@media (min-width: 768px) {
  .container {
    padding: 2rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 3rem;
  }
}

/* Reveal on Scroll Animation */
.reveal {
  position: relative;
  transform: translateY(150px);
  opacity: 0;
  transition: 1s all ease;
}

.reveal.active {
  transform: translateY(0);
  opacity: 1;
}

/* Keyframes for Reveal Animation (Optional, for more complex animations) */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Example usage of fadeInUp animation */
.animate-fade-in-up {
  animation: fadeInUp 0.5s ease-out forwards;
}

/* Additional Utility Classes */
.text-center {
  text-align: center;
}

.mt-4 {
  margin-top: 1rem;
}

.mb-4 {
  margin-bottom: 1rem;
}

.py-4 {
  padding-top: 1rem;
  padding-bottom: 1rem;
}

/* Example Glassmorphism Button */
.glass-button {
  background: var(--glass-bg);
  border: 1px solid var(--glass-border);
  backdrop-filter: var(--glass-backdrop-blur);
  border-radius: 0.5rem;
  padding: 0.75rem 1.5rem;
  color: var(--secondary-color);
  font-family: var(--primary-font);
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.glass-button:hover {
  background: rgba(255, 255, 255, 0.2);
  transform: translateY(-3px);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
}

/* Mobile Menu Styles (Example - Customize as needed) */
.mobile-menu {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.8); /* Adjust transparency as needed */
  backdrop-filter: blur(5px);
  z-index: 1000;
  display: flex;
  justify-content: center;
  align-items: center;
  visibility: hidden;
  opacity: 0;
  transition: all 0.3s ease;
}

.mobile-menu.active {
  visibility: visible;
  opacity: 1;
}

.mobile-menu ul {
  text-align: center;
}

.mobile-menu li {
  margin-bottom: 1rem;
}

.mobile-menu a {
  font-size: 1.5rem;
  color: var(--secondary-color);
  text-decoration: none;
}

/* Back to Top Button (Example) */
.back-to-top {
  position: fixed;
  bottom: 20px;
  right: 20px;
