/* style.css */

@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;700&family=Open+Sans:wght@400;600&display=swap');

/* Design Tokens from Gemini */
:root {
    /* Colors */
    --primary-color-1: #25D366;
    --primary-color-2: #128C7E;
    --white: #FFFFFF;
    --black: #000000;
    --gray-100: #F3F4F6;
    --gray-200: #E5E7EB;
    --gray-300: #D1D5DB;
    --gray-400: #9CA3AF;
    --gray-500: #6B7280;
    --gray-600: #4B5563;
    --gray-700: #374151;
    --gray-800: #1F2937;
    --gray-900: #111827;

    /* Typography */
    --font-family-primary: 'Roboto', sans-serif;
    --font-family-secondary: 'Open Sans', sans-serif;
    --font-weight-regular: 400;
    --font-weight-bold: 700;
    --font-size-base: 1rem; /* 16px */
    --line-height-base: 1.5;

    /* Spacing System (Fluid - Implement with Clamp) */
    --spacing-unit: 1rem; /* Base spacing unit */
    --spacing-xs: clamp(0.25rem, 0.2rem + 0.25vw, 0.5rem);
    --spacing-sm: clamp(0.5rem, 0.4rem + 0.5vw, 0.75rem);
    --spacing-md: clamp(1rem, 0.8rem + 1vw, 1.5rem);
    --spacing-lg: clamp(1.5rem, 1.2rem + 1.5vw, 2.25rem);
    --spacing-xl: clamp(2rem, 1.6rem + 2vw, 3rem);

    /* Border Radius */
    --border-radius-sm: 0.25rem;
    --border-radius-md: 0.5rem;
    --border-radius-lg: 0.75rem;
    --border-radius-xl: 1rem;

    /* Shadows */
    --box-shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
    --box-shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
    --box-shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);

    /* Transitions */
    --transition-duration: 0.3s;
    --transition-easing: ease-in-out;

    /* Glassmorphism */
    --glass-bg: rgba(255, 255, 255, 0.1);
    --glass-backdrop-blur: blur(20px);
    --glass-border: 1px solid rgba(255, 255, 255, 0.2);
}

/* General Styles */
body {
    font-family: var(--font-family-primary);
    font-size: var(--font-size-base);
    line-height: var(--line-height-base);
    color: var(--gray-700);
    background-color: var(--gray-100);
    margin: 0;
    padding: 0;
    overflow-x: hidden; /* Prevent horizontal scrolling */
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-family-secondary);
    font-weight: var(--font-weight-bold);
    color: var(--gray-800);
    margin-bottom: var(--spacing-sm);
}

h1 {
    font-size: 2.5rem;
}

h2 {
    font-size: 2rem;
}

h3 {
    font-size: 1.75rem;
}

p {
    margin-bottom: var(--spacing-md);
}

a {
    color: var(--primary-color-1);
    text-decoration: none;
    transition: color var(--transition-duration) var(--transition-easing);
}

a:hover {
    color: var(--primary-color-2);
}

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-lg);
}

/* Glassmorphism Effect */
.glassmorphism {
    background: var(--glass-bg);
    backdrop-filter: var(--glass-backdrop-blur);
    border: var(--glass-border);
    border-radius: var(--border-radius-lg);
    padding: var(--spacing-md);
}

/* Buttons */
.btn {
    display: inline-block;
    padding: var(--spacing-sm) var(--spacing-md);
    font-weight: var(--font-weight-bold);
    text-align: center;
    text-decoration: none;
    cursor: pointer;
    border-radius: var(--border-radius-md);
    transition: all var(--transition-duration) var(--transition-easing);
    border: none;
}

.btn-primary {
    background-color: var(--primary-color-1);
    color: var(--white);
}

.btn-primary:hover {
    background-color: var(--primary-color-2);
}

.btn-secondary {
    background-color: transparent;
    color: var(--primary-color-1);
    border: 1px solid var(--primary-color-1);
}

.btn-secondary:hover {
    background-color: var(--primary-color-1);
    color: var(--white);
}

/* Forms */
input[type="text"],
input[type="email"],
input[type="password"],
textarea {
    width: 100%;
    padding: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
    border: 1px solid var(--gray-300);
    border-radius: var(--border-radius-sm);
    font-family: var(--font-family-primary);
    font-size: var(--font-size-base);
}

/* Responsive Utilities */
/* Example Breakpoints (Adjust as needed) */
@media (max-width: 768px) {
    .container {
        padding: var(--spacing-md);
    }

    h1 {
        font-size: 2rem;
    }

    h2 {
        font-size: 1.5rem;
    }
}

@media (max-width: 576px) {
    .container {
        padding: var(--spacing-sm);
    }
}

/* Animation */
@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

.fade-in {
    animation: fadeIn 0.5s ease-in-out;
}

/* Reveal on Scroll (Basic Implementation - Requires JS for triggering) */
.reveal {
    opacity: 0;
    transform: translateY(20px);
    transition: all 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}

/* Utility Classes (Tailwind-like) */
.mt-0 { margin-top: 0; }
.mb-0 { margin-bottom: 0; }
.mt-sm { margin-top: var(--spacing-sm); }
.mb-sm { margin-bottom: var(--spacing-sm); }
.mt-md { margin-top: var(--spacing-md); }
.mb-md { margin-bottom: var(--spacing-md); }
.mt-lg { margin-top: var(--spacing-lg); }
.mb-lg { margin-bottom: var(--spacing-lg); }
.text-center { text-align: center; }
.text-primary { color: var(--primary-color-1); }
.bg-primary { background-color: var(--primary-color-1); }
.rounded-md { border-radius: var(--border-radius-md); }
.shadow-md { box-shadow: var(--box-shadow-md); }

/* Additional Styles (Specific to the Messaging App) */
.message-bubble {
    padding: var(--spacing-sm);
    border-radius: var(--border-radius-lg);
    margin-bottom: var(--spacing-sm);
}

.message-bubble.sent {
    background-color: var(--primary-color-1);
    color: var(--white);
    align-self: flex-end; /* Align to the right in a flex container */
}

.message-bubble.received {
    background-color: var(--gray-200);
    color: var(--gray-800);
    align-self: flex-start; /* Align to the left in a flex container */
}

.chat-container {
    display: flex;
    flex-direction: column;
    height: 500px; /* Example height */
    overflow-y: auto; /* Enable scrolling */
    padding: var(--spacing-md);
}

/* Mobile Menu (Basic Styling - Requires JS for functionality) */
.mobile-menu {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.5); /* Semi-transparent background */
    display: none; /* Hidden by default */
    z-index: 1000; /* Ensure it's on top */
}

.mobile-menu.active {
    display: block;
}

.mobile-menu-content {
    position: absolute;
    top: 0;
    right: 0;
    width: 300px;
    height: 100%;
    background-color: var(--white);
    padding: var(--spacing-lg);
    box-shadow: var(--box-shadow-lg);
}

/* Back to Top Button */
#back-to-top {
  position: fixed;
  bottom: 20px;
  right: 20px;
  background-color: var(--primary-color-1);
  color: white;
  padding: 10px 15px;
  border-radius: 5px;
  cursor: pointer;
  display: none; /* Hidden by default, shown by JS */
  z-index: 999;
}

#back-to-top:hover {
  background-color: var(--primary-color-2);
}

