@import url('https://fonts.googleapis.com/css2?family=Roboto+Condensed:wght@400;700&family=Open+Sans:wght@400;600&display=swap');

:root {
    /* Color Palette */
    --primary-color-1: #0B3D91;
    --primary-color-2: #ADD8E6;
    --neutral-color-1: #FFFFFF;
    --neutral-color-2: #F0F0F0;
    --accent-color-1: #FF4500; /* Example accent color */

    /* Typography */
    --heading-font: 'Roboto Condensed', sans-serif;
    --body-font: 'Open Sans', sans-serif;

    /* Spacing System (Fluid) */
    --space-xs: clamp(0.25rem, 0.2vw, 0.5rem);
    --space-sm: clamp(0.5rem, 0.4vw, 0.75rem);
    --space-md: clamp(1rem, 0.8vw, 1.5rem);
    --space-lg: clamp(1.5rem, 1.2vw, 2.25rem);
    --space-xl: clamp(2.25rem, 1.8vw, 3rem);

    /* Glassmorphism */
    --glass-bg: rgba(255, 255, 255, 0.1);
    --glass-border: rgba(255, 255, 255, 0.2);
    --glass-blur: blur(10px);

    /* Animation */
    --animation-duration: 0.3s;
    --animation-easing: ease-out;
}

/* General Styles */
body {
    font-family: var(--body-font);
    color: #333;
    background-color: var(--neutral-color-2);
    margin: 0;
    padding: 0;
    line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--heading-font);
    color: var(--primary-color-1);
    font-weight: 700;
    margin-bottom: var(--space-sm);
}

a {
    color: var(--primary-color-1);
    text-decoration: none;
    transition: color var(--animation-duration) var(--animation-easing);
}

a:hover {
    color: var(--accent-color-1);
}

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-md);
}

/* Glassmorphism Card */
.glass-card {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: var(--space-md);
    backdrop-filter: var(--glass-blur);
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

/* Buttons */
.button {
    display: inline-block;
    padding: var(--space-sm) var(--space-md);
    font-family: var(--heading-font);
    font-weight: 600;
    border-radius: 8px;
    text-align: center;
    text-decoration: none;
    transition: all var(--animation-duration) var(--animation-easing);
    border: none;
    cursor: pointer;
}

.button-primary {
    background-color: var(--primary-color-1);
    color: var(--neutral-color-1);
}

.button-primary:hover {
    background-color: #072b66; /* Darker shade of primary */
}

.button-secondary {
    background-color: transparent;
    color: var(--primary-color-1);
    border: 1px solid var(--primary-color-1);
}

.button-secondary:hover {
    background-color: var(--primary-color-2);
    color: var(--primary-color-1);
}

/* Navigation */
nav {
    background: var(--glass-bg);
    backdrop-filter: var(--glass-blur);
    border-bottom: 1px solid var(--glass-border);
    padding: var(--space-sm) 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

nav .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
}

nav li {
    margin-left: var(--space-md);
}

nav a {
    display: block;
    padding: var(--space-xs) var(--space-sm);
    border-radius: 8px;
}

nav a:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

/* Mobile Menu */
.mobile-menu-button {
    display: none;
    background: none;
    border: none;
    color: var(--primary-color-1);
    font-size: 1.5rem;
    cursor: pointer;
}

.mobile-menu {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.8);
    color: var(--neutral-color-1);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    z-index: 1000;
    opacity: 0;
    visibility: hidden;
    transition: opacity var(--animation-duration) var(--animation-easing), visibility 0s linear var(--animation-duration);
}

.mobile-menu.open {
    opacity: 1;
    visibility: visible;
    transition: opacity var(--animation-duration) var(--animation-easing), visibility 0s linear 0s;
}

.mobile-menu ul {
    list-style: none;
    padding: 0;
    margin: 0;
    text-align: center;
}

.mobile-menu li {
    margin-bottom: var(--space-lg);
}

.mobile-menu a {
    color: var(--neutral-color-1);
    font-size: 1.5rem;
    padding: var(--space-sm) var(--space-md);
    border-radius: 8px;
}

.mobile-menu a:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

.mobile-menu-close {
    position: absolute;
    top: var(--space-md);
    right: var(--space-md);
    background: none;
    border: none;
    color: var(--neutral-color-1);
    font-size: 2rem;
    cursor: pointer;
}

/* Footer */
footer {
    background: var(--primary-color-1);
    color: var(--neutral-color-1);
    padding: var(--space-lg) 0;
    text-align: center;
}

footer a {
    color: var(--primary-color-2);
}

footer a:hover {
    color: var(--neutral-color-1);
}

/* Reveal on Scroll */
.reveal {
    opacity: 0;
    transform: translateY(20px);
    transition: opacity 0.7s ease-in-out, transform 0.7s ease-in-out;
}

.reveal.active {
    opacity: 1;
    transform: translateY(0);
}

/* Bento Grid (Example) */
.bento-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--space-md);
}

.bento-item {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: var(--space-md);
    backdrop-filter: var(--glass-blur);
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

/* Responsive Design */
@media (max-width: 768px) {
    .container {
        padding: var(--space-sm);
    }

    nav ul {
        display: none; /* Hide desktop menu */
    }

    .mobile-menu-button {
        display: block; /* Show mobile menu button */
    }

    .bento-grid {
