script.js.content:
document.addEventListener('DOMContentLoaded', function() {
    // Scroll animation for elements with class 'animate-on-scroll'
    const elements = document.querySelectorAll('.animate-on-scroll');

    function checkSlide() {
        elements.forEach(element => {
            // Calculate the trigger point (e.g., when 80% of the element is visible)
            const slideInAt = (window.scrollY + window.innerHeight) - element.offsetHeight / 5;

            // Bottom of the element
            const elementBottom = element.offsetTop + element.offsetHeight;

            // Is half the element visible?
            const isHalfShown = slideInAt > element.offsetTop;

            // Is it not scrolled past?
            const isNotScrolledPast = window.scrollY < elementBottom;

            if (isHalfShown && isNotScrolledPast) {
                element.classList.add('active');
            } else if (!isNotScrolledPast) { // Keep active class if scrolled past the trigger point but not past the bottom
                element.classList.remove('active');
            }
        });
    }

    window.addEventListener('scroll', debounce(checkSlide));

    // Debounce function to limit the rate at which a function can fire.
    function debounce(func, wait = 20, immediate = false) { // Changed immediate to false
        var timeout;
        return function() {
            var context = this, args = arguments;
            var later = function() {
                timeout = null;
                if (!immediate) func.apply(context, args);
            };
            var callNow = immediate && !timeout;
            clearTimeout(timeout);
            timeout = setTimeout(later, wait);
            if (callNow) func.apply(context, args);
        };
    };
});

