  transition: color 0.3s ease-in-out;
}

.nav-links a:hover {
  color: var(--primary-color-1);
}

/* --- Hero Section --- */
.hero {
  background: linear-gradient(135deg, #f7fafc 0%, #edf2f7 100%);
  padding: clamp(4rem, 8vw, 8rem) 0;
  text-align: center;
}

.hero-content {
  margin-bottom: clamp(2rem, 4vw, 4rem);
}

.hero-image {
  max-width: 100%;
  height: auto;
  border-radius: 1rem;
  box-shadow: 0 8px 16px var(--shadow-color);
}

/* --- Buttons --- */
.btn {
  display: inline-block;
  padding: clamp(0.75rem, 1.5vw, 1rem) clamp(1.5rem, 3vw, 2rem);
  font-weight: 500;
  text-decoration: none;
  border-radius: 0.5rem;
  transition: all 0.3s ease-in-out;
  box-shadow: 0 4px 6px var(--shadow-color);
}

.btn-primary {
  background-color: var(--primary-color-1);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-color-2);
  transform: translateY(-2px);
}

.btn-secondary {
  background-color: transparent;
  color: var(--primary-color-1);
  border: 2px solid var(--primary-color-1);
}

.btn-secondary:hover {
  background-color: rgba(var(--primary-color-1), 0.1);
  transform: translateY(-2px);
}

/* --- Features Section --- */
.features {
  padding: clamp(4rem, 8vw, 6rem) 0;
  background-color: #fff;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: clamp(2rem, 4vw, 4rem);
}

.feature-item {
  padding: clamp(2rem, 3vw, 3rem);
  background-color: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(5px);
  border-radius: 1rem;
  box-shadow: 0 4px 8px var(--shadow-color);
  transition: transform 0.3s ease-in-out;
}

.feature-item:hover {
  transform: translateY(-5px);
}

.feature-item h3 {
  font-size: clamp(1.5rem, 3vw, 2rem);
  margin-bottom: 1rem;
  color: #2d3748;
}

/* --- Testimonials Section --- */
.testimonials {
  padding: clamp(4rem, 8vw, 6rem) 0;
  background-color: #f7fafc;
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: clamp(1.5rem, 3vw, 3rem);
}

.testimonial-item {
  padding: clamp(1.5rem, 3vw, 2rem);
  background-color: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(5px);
  border-radius: 0.75rem;
  box-shadow: 0 2px 4px var(--shadow-color);
  transition: transform 0.3s ease-in-out;
}

.testimonial-item:hover {
  transform: translateY(-3px);
}

.testimonial-item p {
  margin-bottom: 0.5rem;
}

.testimonial-author {
  font-weight: 500;
  color: var(--primary-color-1);
}

/* Adjustments for better contrast in testimonials */
.testimonial-item {
    background-color: rgba(255, 255, 255, 0.85);
    border: 1px solid rgba(255, 255, 255, 0.3);
}

.testimonial-item p {
    color: #333;
}

/* More distinct hero gradient */
.hero {
    background: linear-gradient(135deg, #f0f0f0 0%, #e2e8f0 100%);
}

/* More noticeable hover states */
.nav-links a:hover, .btn:hover {
    opacity: 0.85;
}

/* Smoother font size transitions */
h1 {
    font-size: clamp(2.75rem, 6vw, 4.5rem);
}

h2 {
    font-size: clamp(2.25rem, 4.5vw, 3.25rem);
}

p {
    font-size: clamp(1.1rem, 2.2vw, 1.3rem);
}

/* Enhanced glassmorphism effect */
.testimonial-item {
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.2);
}

/* --- Footer --- */
footer {
  background-color: #2d3748;
  color: #cbd5e0;
  text-align: center;
  padding: 2rem 0;
}

/* --- Animations --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  animation: fadeIn 0.8s ease-out forwards;
}

/* Micro-interaction for buttons */
.btn {
  transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;
}

.btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 10px rgba(0, 0, 0, 0.15);
}

/* --- Media Queries for Responsiveness --- */
@media (max-width: 768px) {
  .nav-links {
    flex-direction: column;
    align-items: center;
  }

  .nav-links li {
    margin: 0.5rem 0;
  }

  .hero {
    padding: 4rem 2rem;
  }

  .hero h1 {
    font-size: 2.5rem;
  }
}

