/* App.css */

/* Design Tokens-Aware Styling */
:root {
  --primary-color: #282c34; /* Dark background */
  --secondary-color: #61dafb; /* Accent color */
  --text-color: #ffffff; /* White text */
  --font-family-base: 'Roboto', sans-serif;
  --font-family-accent: 'Open Sans', sans-serif;
  --shadow-color: rgba(0, 0, 0, 0.3);
  --glass-bg: rgba(255, 255, 255, 0.1); /* Adjust opacity as needed */
}

/* General Styles */
body {
  font-family: var(--font-family-base);
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  background-color: var(--primary-color);
  color: var(--text-color);
  line-height: 1.6;
  overflow-x: hidden; /* Prevent horizontal scroll */
}

/* Smooth Scrolling */
html {
  scroll-behavior: smooth;
}

/* Enhanced Container */
.container {
  max-width: clamp(800px, 80vw, 1200px); /* Fluid container width */
  margin: 0 auto;
  padding: clamp(20px, 3vw, 40px); /* Fluid padding */
}

/* Typography */
h1, h2, h3 {
  font-family: var(--font-family-accent);
  font-weight: 700;
  margin-bottom: clamp(0.5rem, 1vw, 1rem);
  color: var(--secondary-color);
  text-shadow: 0 2px 4px var(--shadow-color); /* Subtle text shadow */
}

h1 {
  font-size: clamp(2.5rem, 4vw, 4rem); /* Responsive font size */
  letter-spacing: -0.05em;
}

h2 {
  font-size: clamp(2rem, 3vw, 3rem);
}

h3 {
  font-size: clamp(1.5rem, 2.5vw, 2.5rem);
}

p {
  font-size: clamp(1rem, 1.5vw, 1.2rem); /* Responsive paragraph size */
  margin-bottom: clamp(0.5rem, 1vw, 1rem);
}

/* Links */
a {
  color: var(--secondary-color);
  text-decoration: none;
  transition: color 0.3s ease-in-out, text-shadow 0.3s ease-in-out;
  text-shadow: 0 1px 2px var(--shadow-color);
}

a:hover {
  color: #fff; /* Hover color */
  text-shadow: 0 3px 6px var(--shadow-color); /* Enhanced hover shadow */
}

/* Buttons - Glassmorphism 2.0 */
button,
.button-like {
  background-color: var(--glass-bg); /* Glassmorphic background */
  color: var(--text-color);
  padding: clamp(10px, 1.5vw, 15px) clamp(20px, 3vw, 30px); /* Fluid padding */
  border: 1px solid rgba(255, 255, 255, 0.1); /* Subtle border */
  border-radius: 10px;
  cursor: pointer;
  font-size: clamp(1rem, 1.2vw, 1.2rem); /* Fluid font size */
  transition: background-color 0.3s ease-in-out, transform 0.2s ease-in-out, box-shadow 0.3s ease-in-out;
  box-shadow: 0 4px 6px var(--shadow-color);
  backdrop-filter: blur(10px); /* Glassmorphism blur */
  -webkit-backdrop-filter: blur(10px); /* For Safari */
}

button:hover,
.button-like:hover {
  background-color: rgba(255, 255, 255, 0.2); /* Darker glass on hover */
  transform: translateY(-2px); /* Slight lift on hover */
  box-shadow: 0 6px 10px var(--shadow-color);
}

button:active,
.button-like:active {
  transform: translateY(0); /* No lift on active */
  box-shadow: 0 2px 4px var(--shadow-color);
}

/* Sections */
section {
  margin-bottom: clamp(3rem, 5vw, 5rem);
}

/* Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in {
  animation: fadeIn 0.8s ease-out forwards;
}

/* Micro-Interaction: Button Ripple Effect (Example) */
.ripple-effect {
  position: relative;
  overflow: hidden;
}

.ripple-effect:after {
  content: '';
  display: block;
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%) translateY(-50%);
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.4); /* Ripple color */
  opacity: 0;
  pointer-events: none;
  transition: width 0.5s ease-out, height 0.5s ease-out, opacity 0.5s ease-out;
}

.ripple-effect:active:after {
  width: 200%;
  height: 200%;
  opacity: 1;
}

/* Media Queries for Enhanced Responsiveness */
@media (max-width: 768px) {
  .container {
    padding: 10px;
  }

  h1 {
    font-size: 2rem;
  }

  h2 {
    font-size: 1.75rem;
  }

  h3 {
    font-size: 1.25rem;
  }
}

/* Example Flexbox Layout */
.flex-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

/* Example Grid Layout */
.grid-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 20px;
}

/* Glassmorphism Card */
.glass-card {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(8.5px);
  -webkit-backdrop-filter: blur(8.5px);
  border: 1px solid rgba(255, 255, 255, 0.23);
  padding: 20px;
}

