import React, { useState } from 'react';

const ContactForm = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
  });
  const [formErrors, setFormErrors] = useState({});
  const [submissionStatus, setSubmissionStatus] = useState(null);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
    setFormErrors({
      ...formErrors,
      [e.target.name]: '', // Clear error on change
    });
  };

  const validateForm = () => {
    let errors = {};
    if (!formData.name) {
      errors.name = 'Name is required';
    }
    if (!formData.email) {
      errors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      errors.email = 'Email is invalid';
    }
    if (!formData.message) {
      errors.message = 'Message is required';
    }
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (validateForm()) {
      try {
        const response = await fetch('/api/contact', { // Ensure your backend route is /api/contact
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(formData),
        });

        if (response.ok) {
          setSubmissionStatus('success');
          setFormData({ name: '', email: '', message: '' }); // Reset form
        } else {
          setSubmissionStatus('error');
        }
      } catch (error) {
        console.error('Submission error:', error);
        setSubmissionStatus('error');
      }
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4 fade-in">
      <div>
        <label htmlFor="name" className="block text-sm font-medium text-gray-700">Name</label>
        <input
          type="text"
          id="name"
          name="name"
          value={formData.name}
          onChange={handleChange}
          className={`mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm ${formErrors.name ? 'border-red-500' : ''}`}
        />
        {formErrors.name && <p className="mt-2 text-sm text-red-600">{formErrors.name}</p>}
      </div>

      <div>
        <label htmlFor="email" className="block text-sm font-medium text-gray-700">Email</label>
        <input
          type="email"
          id="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          className={`mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm ${formErrors.email ? 'border-red-500' : ''}`}
        />
        {formErrors.email && <p className="mt-2 text-sm text-red-600">{formErrors.email}</p>}
      </div>

      <div>
        <label htmlFor="message" className="block text-sm font-medium text-gray-700">Message</label>
        <textarea
          id="message"
          name="message"
          value={formData.message}
          onChange={handleChange}
          rows="4"
          className={`mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500 sm:text-sm ${formErrors.message ? 'border-red-500' : ''}`}
        ></textarea>
        {formErrors.message && <p className="mt-2 text-sm text-red-600">{formErrors.message}</p>}
      </div>

      <div>
        <button type="submit" className="button-like ripple-effect">
          Send Message
        </button>
      </div>

      {submissionStatus === 'success' && (
        <div className="text-green-600">Message sent successfully!</div>
      )}
      {submissionStatus === 'error' && (
        <div className="text-red-600">An error occurred. Please try again.</div>
      )}
    </form>
  );
};

export default ContactForm;

script.js.content:
document.addEventListener('DOMContentLoaded', () => {
  // Sticky Header
  const header = document.querySelector('header');
  let lastScrollTop = 0;

  window.addEventListener('scroll', () => {
    let scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    if (scrollTop > lastScrollTop) {
      // Scrolling down
      header.classList.add('transform', '-translate-y-full');
    } else {
      // Scrolling up
      header.classList.remove('transform', '-translate-y-full');
    }
    lastScrollTop = scrollTop <= 0 ? 0 : scrollTop; // For Mobile or negative scrolling
  });

  // Fade-in Animation (Example - you might need to adapt this)
  const elementsToFadeIn = document.querySelectorAll('.animate-fade-in-up');

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('fade-in-up'); // Add a class to trigger the animation
        observer.unobserve(entry.target); // Stop observing after animating once
      }
    });
  }, {
    threshold: 0.2 // Adjust as needed
  });

  elementsToFadeIn.forEach(element => {
    observer.observe(element);
  });
});

