@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&family=Open+Sans:wght@400;600&display=swap');

:root {
  /* Primary Colors */
  --primary-color-100: #E0F2FE;
  --primary-color-500: #3B82F6;
  --primary-color-900: #1E3A8A;

  /* Typography */
  --font-family-primary: 'Roboto', sans-serif;
  --font-family-secondary: 'Open Sans', sans-serif;

  /* Spacing System (Fluid - Implement using clamp) */
  --space-unit: 1rem; /* Base unit */
  --space-xs: clamp(0.25rem, calc(0.25rem + 0.1vw), 0.5rem);
  --space-sm: clamp(0.5rem, calc(0.5rem + 0.2vw), 0.75rem);
  --space-md: clamp(0.75rem, calc(0.75rem + 0.3vw), 1.25rem);
  --space-lg: clamp(1.25rem, calc(1.25rem + 0.4vw), 2rem);
  --space-xl: clamp(2rem, calc(2rem + 0.5vw), 3rem);

  /* Font Sizes (Using Clamp for Responsiveness) */
  --font-size-xs: clamp(0.75rem, calc(0.75rem + 0.1vw), 0.875rem);
  --font-size-sm: clamp(0.875rem, calc(0.875rem + 0.1vw), 1rem);
  --font-size-base: clamp(1rem, calc(1rem + 0.1vw), 1.125rem);
  --font-size-lg: clamp(1.125rem, calc(1.125rem + 0.2vw), 1.25rem);
  --font-size-xl: clamp(1.25rem, calc(1.25rem + 0.2vw), 1.5rem);
  --font-size-2xl: clamp(1.5rem, calc(1.5rem + 0.3vw), 1.875rem);
  --font-size-3xl: clamp(1.875rem, calc(1.875rem + 0.4vw), 2.25rem);
  --font-size-4xl: clamp(2.25rem, calc(2.25rem + 0.5vw), 3rem);
}

/* General Styles */
body {
  font-family: var(--font-family-primary);
  color: #333;
  line-height: 1.6;
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  background-color: #f9f9f9; /* Light background */
}

/* Typography */
h1, h2, h3 {
  font-family: var(--font-family-primary);
  font-weight: 700;
  color: var(--primary-color-900);
  margin-bottom: var(--space-sm);
}

h1 {
  font-size: var(--font-size-4xl);
}

h2 {
  font-size: var(--font-size-3xl);
}

h3 {
  font-size: var(--font-size-2xl);
}

p {
  font-family: var(--font-family-secondary);
  font-size: var(--font-size-base);
  margin-bottom: var(--space-md);
}

a {
  color: var(--primary-color-500);
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover {
  color: var(--primary-color-900);
}

/* Layout */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--space-lg);
}

/* Glassmorphism Effect */
.glassmorphism {
  background-color: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 1rem;
  padding: var(--space-lg);
}

/* Buttons */
.btn {
  display: inline-block;
  padding: var(--space-sm) var(--space-md);
  font-size: var(--font-size-base);
  font-weight: 600;
  text-align: center;
  text-decoration: none;
  border-radius: 0.5rem;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.btn-primary {
  background-color: var(--primary-color-500);
  color: #fff;
  border: none;
}

.btn-primary:hover {
  background-color: var(--primary-color-900);
}

.btn-secondary {
  background-color: transparent;
  color: var(--primary-color-500);
  border: 1px solid var(--primary-color-500);
}

.btn-secondary:hover {
  background-color: var(--primary-color-100);
}

/* Forms */
input[type="text"],
input[type="email"],
textarea {
  width: 100%;
  padding: var(--space-sm);
  margin-bottom: var(--space-md);
  border: 1px solid #ccc;
  border-radius: 0.25rem;
  font-size: var(--font-size-base);
}

/* Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes slideInFromBottom {
  from {
    transform: translateY(50px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.fade-in {
  animation: fadeIn 0.5s ease-in-out;
}

.slide-in-bottom {
  animation: slideInFromBottom 0.5s ease-in-out;
}

/* Responsive Design */
@media (max-width: 768px) {
  .container {
    padding: var(--space-md);
  }

  h1 {
    font-size: var(--font-size-3xl);
  }

  h2 {
    font-size: var(--font-size-2xl);
  }

  h3 {
    font-size: var(--font-size-xl);
  }
}

