  /* cursor: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="40" height="48" viewport="0 0 40 48" cursor="auto"><path d="M20 0 L30 20 L40 24 L30 28 L20 48 L10 28 L0 24 L10 20 Z" /></svg>') 16 0, auto; */
}

/* General Styles */
.container {
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
}

/* Flickering Animation */
@keyframes flicker {
