/**
 * script.js
 *
 * This file contains JavaScript functionality for the smartphone showcase website.
 * It includes animations, scroll-triggered effects, form validation, and other
 * interactive elements to enhance the user experience.
 *
 * @file This file contains the JavaScript code for the website.
 * @version 1.0
 */

// Function to handle scroll-triggered animations
function handleScrollAnimations() {
    const elements = document.querySelectorAll('.animate-on-scroll');

    elements.forEach(element => {
        if (isElementInViewport(element)) {
            element.classList.add('animate-in');
        }
    });
}

/**
 * Checks if an element is within the viewport.
 *
 * @param {HTMLElement} el - The element to check.
 * @returns {boolean} - True if the element is in the viewport, false otherwise.
 */
function isElementInViewport(el) {
    const rect = el.getBoundingClientRect();
    return (
        rect.top >= 0 &&
        rect.left >= 0 &&
        rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
        rect.right <= (window.innerWidth || document.documentElement.clientWidth)
    );
}

// Function to validate the contact form
function validateContactForm() {
    const form = document.getElementById('contactForm');
    if (!form) return; // Exit if the form doesn't exist

    form.addEventListener('submit', function(event) {
        let isValid = true;

        const nameInput = document.getElementById('name');
        const emailInput = document.getElementById('email');
        const messageInput = document.getElementById('message');

        // Reset error messages
        resetValidation(nameInput);
        resetValidation(emailInput);
        resetValidation(messageInput);

        // Validate name
        if (!nameInput.value.trim()) {
            showValidationError(nameInput, 'Name is required');
            isValid = false;
        }

        // Validate email
        if (!emailInput.value.trim()) {
            showValidationError(emailInput, 'Email is required');
            isValid = false;
        } else if (!isValidEmail(emailInput.value.trim())) {
            showValidationError(emailInput, 'Invalid email format');
            isValid = false;
        }

        // Validate message
        if (!messageInput.value.trim()) {
            showValidationError(messageInput, 'Message is required');
            isValid = false;
        }

        if (!isValid) {
            event.preventDefault(); // Prevent form submission if validation fails
        }
    });
}

/**
 * Validates if the input is a valid email format.
 *
 * @param {string} email - The email address to validate.
 * @returns {boolean} - True if the email is valid, false otherwise.
 */
function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

/**
 * Shows a validation error message for a specific input field.
 *
 * @param {HTMLElement} inputElement - The input element to show the error for.
 * @param {string} message - The error message to display.
 */
function showValidationError(inputElement, message) {
    inputElement.classList.add('is-invalid');
    let errorSpan = inputElement.nextElementSibling; // Assuming error span is next sibling

    if (!errorSpan || !errorSpan.classList.contains('invalid-feedback')) {
        // Create error span if it doesn't exist
        errorSpan = document.createElement('span');
        errorSpan.className = 'invalid-feedback';
        inputElement.parentNode.appendChild(errorSpan);
    }
    errorSpan.textContent = message;
}

/**
 * Resets the validation state of an input field.
 *
 * @param {HTMLElement} inputElement - The input element to reset.
 */
function resetValidation(inputElement) {
    inputElement.classList.remove('is-invalid');
    let errorSpan = inputElement.nextElementSibling;
    if (errorSpan && errorSpan.classList.contains('invalid-feedback')) {
        errorSpan.textContent = ''; // Clear error message
    }
}

// Function to initialize animations and effects
function initialize() {
    // Initial call to handle scroll animations on page load
    handleScrollAnimations();

    // Attach scroll event listener for animations
    window.addEventListener('scroll', handleScrollAnimations);

    // Initialize form validation
    validateContactForm();
}

// Initialize the script when the DOM is fully loaded
document.addEventListener('DOMContentLoaded', initialize);

