/* style.css */

/* CSS Variables (Design Tokens) */
:root {
    --primary-color-light: #E9F5F2;
    --primary-color-medium: #A2D9CE;
    --primary-color-dark: #52BE80;

    --font-family-primary: 'Poppins', sans-serif;
    --font-family-secondary: 'Open Sans', sans-serif;

    /* Fluid spacing system using clamp() */
    --space-unit: 1rem;
    --space-sm: clamp(0.5rem, 0.3rem + 0.5vw, 0.75rem);
    --space-md: clamp(1rem, 0.6rem + 1vw, 1.5rem);
    --space-lg: clamp(2rem, 1.2rem + 2vw, 3rem);
    --space-xl: clamp(4rem, 2.4rem + 4vw, 6rem);

    --border-radius: 0.5rem;
}

/* General Styles */
body {
    font-family: var(--font-family-secondary);
    line-height: 1.6;
    color: #333;
    background-color: var(--primary-color-light);
    margin: 0;
    padding: 0;
    overflow-x: hidden; /* Prevent horizontal scroll */
}

/* Typography */
h1, h2, h3 {
    font-family: var(--font-family-primary);
    font-weight: 700;
    color: #2d3748; /* Gray-800 from tailwind */
}

h1 {
    font-size: clamp(2.5rem, 2rem + 3vw, 4rem);
    line-height: 1.1;
}

h2 {
    font-size: clamp(2rem, 1.5rem + 2vw, 3rem);
}

h3 {
    font-size: clamp(1.5rem, 1rem + 1.5vw, 2.25rem);
}

p {
    font-size: 1rem;
    color: #4a5568; /* Gray-700 from tailwind */
}

a {
    color: var(--primary-color-dark);
    text-decoration: none;
    transition: color 0.3s ease;
}

a:hover {
    color: #38a169; /* Green-600 from tailwind */
}

/* Layout & Spacing */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-md);
}

section {
    padding: var(--space-lg) 0;
}

/* Glassmorphism Effect (Example - Header) */
header {
    background-color: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.2);
    padding: var(--space-sm) 0;
    position: sticky;
    top: 0;
    z-index: 10;
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
}

nav li {
    margin-left: var(--space-md);
}

nav a {
    display: block;
    padding: var(--space-sm);
    border-radius: var(--border-radius);
    transition: background-color 0.3s ease;
}

nav a:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

/* Buttons */
.button {
    background-color: var(--primary-color-dark);
    color: white;
    padding: var(--space-sm) var(--space-md);
    border-radius: var(--border-radius);
    display: inline-block;
    transition: background-color 0.3s ease, transform 0.2s ease;
    border: none;
    cursor: pointer;
    font-size: 1rem;
}

.button:hover {
    background-color: #38a169; /* Green-600 from tailwind */
    transform: translateY(-2px);
}

/* Animations */
@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Apply animations */
.fade-in {
    animation: fadeIn 0.5s ease forwards;
}

.fade-in-up {
    animation: fadeInUp 0.5s ease forwards;
}

/* Mobile Responsiveness */
@media (max-width: 768px) {
    .container {
        padding: var(--space-sm);
    }

    nav ul {
        flex-direction: column;
        align-items: flex-start;
    }

    nav li {
        margin-left: 0;
        margin-bottom: var(--space-sm);
    }
}

/* Accessibility (Example) */
a:focus,
button:focus {
    outline: 2px solid var(--primary-color-dark);
    outline-offset: 2px;
}

/* Additional utility classes (Tailwind-like) */
.text-center {
    text-align: center;
}

.mt-0 {
    margin-top: 0;
}

.mb-4 {
