    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

/* Typography */
h1, h2, h3 {
    font-family: var(--font-headline);
    font-weight: 700;
    color: var(--color-text-secondary);
    line-height: 1.2;
}

h1 {
    font-size: clamp(2.5rem, 5vw, 4rem);
    margin-bottom: clamp(1rem, 2vw, 1.5rem);
}

h2 {
    font-size: clamp(2rem, 4vw, 3rem);
    margin-bottom: clamp(0.75rem, 1.5vw, 1.25rem);
}

h3 {
    font-size: clamp(1.5rem, 3vw, 2rem);
    margin-bottom: clamp(0.5rem, 1vw, 1rem);
}

p {
    font-size: clamp(1rem, 1.5vw, 1.2rem);
    margin-bottom: clamp(0.5rem, 1vw, 1rem);
}

a {
    color: var(--color-primary);
    text-decoration: none;
    transition: color 0.3s ease;
}

a:hover {
    color: var(--color-accent);
}

/* Colors */
:root {
    --color-bg-primary: #F0F0F0;
    --color-text-primary: #333333;
    --color-text-secondary: #777777;
    --color-primary: #007bff; /* Example primary color */
    --color-accent: #0056b3; /* Example accent color */
    --color-glass-bg: rgba(255, 255, 255, 0.2);
    --color-glass-border: rgba(255, 255, 255, 0.3);
    --color-shadow: rgba(0, 0, 0, 0.3);
}

/* Typography */
:root {
    --font-headline: 'Roboto Slab', serif;
    --font-body: 'Open Sans', sans-serif;
}

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: clamp(1rem, 2vw, 2rem);
}

/* Glassmorphism */
.glassmorphic {
    background: var(--color-glass-bg);
    border: 1px solid var(--color-glass-border);
    border-radius: 16px;
    box-shadow: 0 8px 32px var(--color-shadow);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px); /* For Safari */
    padding: clamp(1.5rem, 3vw, 3rem);
}

/* Buttons */
.btn {
    display: inline-block;
    padding: clamp(0.75rem, 1.5vw, 1rem) clamp(1.5rem, 2vw, 2rem);
    font-size: clamp(1rem, 1.2vw, 1.1rem);
    font-weight: 600;
    text-align: center;
    text-decoration: none;
    cursor: pointer;
    border: none;
    border-radius: 8px;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.btn:hover {
    transform: translateY(-2px) scale(1.02);
    box-shadow: 0 4px 12px var(--color-shadow);
}

.btn-primary {
    background-color: var(--color-primary);
    color: #fff;
}

.btn-secondary {
    background-color: transparent;
    color: var(--color-primary);
    border: 2px solid var(--color-primary);
}

/* Navigation */
nav {
    background-color: var(--color-glass-bg);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    padding: clamp(0.5rem, 1vw, 1rem) 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

nav ul {
    list-style: none;
    display: flex;
    justify-content: center;
    align-items: center;
}

nav li {
    margin: 0 clamp(0.75rem, 1.5vw, 1.5rem);
}

nav a {
    display: block;
    padding: clamp(0.5rem, 1vw, 0.75rem);
    border-radius: 8px;
    transition: background-color 0.3s ease;
}

nav a:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

/* Header */
header {
    padding: clamp(2rem, 4vw, 5rem) 0;
    text-align: center;
}

header h1 {
    margin-bottom: clamp(1rem, 2vw, 2rem);
}

header p {
    font-size: clamp(1.2rem, 2vw, 1.5rem);
    max-width: 800px;
    margin: 0 auto;
}

/* Footer */
footer {
    background-color: var(--color-bg-secondary);
    color: var(--color-text-secondary);
    text-align: center;
    padding: clamp(1rem, 2vw, 2rem) 0;
    font-size: clamp(0.8rem, 1vw, 1rem);
}

/* Sections */
section {
    padding: clamp(3rem, 5vw, 6rem) 0;
}

section:nth-child(even) {
    background-color: rgba(0, 0, 0, 0.02);
}

/* Animations */
@keyframes reveal {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.reveal {
    animation: reveal 1s ease-out forwards;
}

/* Utility Classes */
.text-center {
    text-align: center;
}

/* Grid Layout Example (For more complex layouts) */
.grid-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: clamp(1rem, 2vw, 2rem);
}

/* Responsive Images */
img {
    max-width: 100%;
    height: auto;
    display: block;
}

