document.addEventListener('DOMContentLoaded', function() {

    // Smooth scrolling to sections
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();

            document.querySelector(this.getAttribute('href')).scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });
        });
    });

    // Parallax effect in the hero section
    const heroSection = document.getElementById('hero');

    if (heroSection) {
        window.addEventListener('scroll', function() {
            let offset = window.pageYOffset;
            heroSection.style.backgroundPositionY = offset * 0.4 + 'px'; // Adjust the multiplier for speed
        });
    }


    // Newsletter form submission handling
    const newsletterForm = document.getElementById('newsletter-form');

    if (newsletterForm) {
        newsletterForm.addEventListener('submit', function(event) {
            event.preventDefault(); // Prevent the default form submission

            const emailInput = document.getElementById('email');
            const email = emailInput.value.trim();

            if (!isValidEmail(email)) {
                displayFeedback('Please enter a valid email address.', 'error');
                return;
            }

            // Simulate form submission (replace with actual API call)
            setTimeout(() => {
                displayFeedback('Thank you for subscribing!', 'success');
                newsletterForm.reset(); // Clear the form
            }, 1000); // Simulate a 1-second delay
        });
    }

    // Email validation function
    function isValidEmail(email) {
        const emailRegex = /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/g;
        return emailRegex.test(email);
    }

    // Feedback display function
    function displayFeedback(message, type) {
        const feedbackElement = document.getElementById('feedback-message');
        feedbackElement.textContent = message;
        feedbackElement.className = `feedback ${type}`;
        feedbackElement.style.display = 'block';

        setTimeout(() => {
            feedbackElement.style.display = 'none';
        }, 3000);
    }
});

