}

a {
  color: var(--accent-color);
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover {
  color: #00e06f; /* Slightly darker green on hover */
}

/* Layout */
.container {
  width: min(90%, 1200px);
  margin-inline: auto;
  padding: var(--space-lg) 0;
}

/* Header Styles */
header {
  background-color: rgba(33, 33, 33, 0.8);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 10;
  padding: var(--space-sm) 0;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

nav .logo {
    font-family: var(--font-primary);
    font-size: 1.5rem;
    font-weight: bold;
    color: white;
}

nav ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  gap: var(--space-md);
}

nav a {
  display: inline-block;
  padding: var(--space-xs) var(--space-sm);
  border-radius: 5px;
  transition: transform 0.3s ease, background-color 0.3s ease;
}

nav a:hover {
  transform: translateY(-2px);
  background-color: rgba(0, 255, 127, 0.1); /* Subtle green hover */
}

/* Hero Section */
#hero {
  background-image: url("assets/hero_background.png");
  background-size: cover;
  background-position: center;
  padding: var(--space-xl) 0;
  text-align: center;
  position: relative;
  overflow: hidden; /* Clip the animation */
}

#hero::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5); /* Dark overlay for readability */
  z-index: 1;
}

#hero .container {
  position: relative;
  z-index: 2; /* Ensure content is above the overlay */
}

#hero h1, #hero p {
  color: white;
}

/* Content Sections (About, Programs, Pricing) */
section {
  padding: var(--space-xl) 0;
}

section:nth-child(even) {
  background-color: var(--primary-color-2);
}

.glass-card {
  background: rgba(33, 33, 33, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(10px);
  padding: var(--space-lg);
  margin-bottom: var(--space-lg);
  transition: transform 0.3s ease;
}

.glass-card:hover {
  transform: translateY(-5px);
}

/* Pricing Section */
#pricing .pricing-tiers {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--space-lg);
}

.pricing-tier {
  background: rgba(33, 33, 33, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(10px);
  padding: var(--space-lg);
  text-align: center;
  transition: transform 0.3s ease;
}

.pricing-tier:hover {
  transform: translateY(-5px);
}

.pricing-tier h3 {
  margin-bottom: var(--space-sm);
}

.pricing-tier .price {
  font-size: 2rem;
  font-weight: bold;
  color: var(--accent-color);
  margin-bottom: var(--space-md);
}

.pricing-tier ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.pricing-tier li {
  margin-bottom: var(--space-xs);
}

/* Call to Action Buttons */
.cta-button {
  display: inline-block;
  padding: var(--space-sm) var(--space-lg);
  font-family: var(--font-primary);
  font-weight: bold;
  border-radius: 8px;
  text-decoration: none;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

.cta-button.primary {
    background-color: var(--accent-color);
    color: var(--primary-color-1);
}

.cta-button.secondary {
    background-color: transparent;
    color: var(--accent-color);
    border: 2px solid var(--accent-color);
}

.cta-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.3);
}

/* Newsletter Section */
#newsletter {
  background-color: var(--primary-color-2);
  padding: var(--space-xl) 0;
  text-align: center;
}

#newsletter h2 {
  margin-bottom: var(--space-md);
}

#newsletter form {
  display: flex;
  flex-direction: column;
  align-items: center;
}

#newsletter input[type="email"] {
  padding: var(--space-sm);
  border: none;
  border-radius: 8px;
  margin-bottom: var(--space-sm);
  width: 70%;
  max-width: 400px;
  background-color: rgba(255, 255, 255, 0.1);
  color: white;
}

#newsletter input[type="email"]::placeholder {
  color: rgba(255, 255, 255, 0.5);
}

#newsletter input[type="email"]:focus {
  outline: none;
  box-shadow: 0 0 5px rgba(0, 255, 127, 0.5);
}

#newsletter .validation-message {
    color: #ff4d4d; /* Red color for error */
    margin-top: var(--space-xs);
    font-size: 0.9rem;
}

#newsletter .success-message {
    color: var(--accent-color); /* Green color for success */
    margin-top: var(--space-xs);
    font-size: 0.9rem;
}

/* Footer */
footer {
  background-color: var(--primary-color-2);
  padding: var(--space-md) 0;
  text-align: center;
  font-size: 0.8rem;
  color: #aaa;
  color: rgba(255, 255, 255, 0.6); /* Improved contrast */
}

/* Animations */
@keyframes reveal {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-on-scroll {
    opacity: 0;
    transform: translateY(20px);
    transition: all 0.5s ease-out;
}

.animate-on-scroll.animated {
    opacity: 1;
    transform: translateY(0);
}

/* Responsive Design (beyond clamp()) */
@media (max-width: 768px) {
  nav ul {
    flex-direction: column;
    text-align: center;
  }

  #pricing .pricing-tiers {
    grid-template-columns: 1fr; /* Stack on smaller screens */
  }

  #newsletter form {
    flex-direction: column; /* Stack elements vertically */
    align-items: stretch; /* Full width on mobile */
  }

  #newsletter input[type="email"] {
    width: 100%; /* Full width input */
    margin-right: 0; /* Remove right margin */
    margin-bottom: var(--space-sm); /* Add margin to bottom */
  }

  #newsletter button {
    width: 100%; /* Full width button */
  }
}

