document.addEventListener('DOMContentLoaded', function() {
  // Smooth scrolling for navigation links
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
      e.preventDefault();

      document.querySelector(this.getAttribute('href')).scrollIntoView({
        behavior: 'smooth',
        block: 'start' // Align the top of the element to the top of the viewport
      });
    });
  });

  // Simple hover effect (example - can be expanded)
  const hoverElements = document.querySelectorAll('.hover-effect'); // Add this class to elements you want the hover effect on
  hoverElements.forEach(element => {
    element.addEventListener('mouseenter', () => {
      element.style.transform = 'translateY(-2px) scale(1.02)';
      element.style.transition = 'transform 0.3s ease'; // Smooth transition
    });

    element.addEventListener('mouseleave', () => {
      element.style.transform = 'translateY(0) scale(1)';
      element.style.transition = 'transform 0.3s ease'; // Smooth transition
    });
  });

  // Reveal animation trigger (example - can be expanded)
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add('show');
        observer.unobserve(entry.target); // Only animate once
      }
    });
  });

  const hiddenElements = document.querySelectorAll('.hidden'); // Add this class to elements you want to reveal
  hiddenElements.forEach((el) => observer.observe(el));

