style.css.content:
/* style.css */

:root {
    /* Color Palette */
    --primary-color-1: #1E293B; /* Dark background */
    --primary-color-2: #CBD5E1; /* Light text */
    --primary-color-3: #64748B; /* Medium gray */

    /* Typography */
    --font-family-primary: 'Space Grotesk', sans-serif;
    --font-family-secondary: 'Inter', sans-serif;

    /* Spacing System - Fluid */
    --space-xs: clamp(0.5rem, 1vw, 0.75rem);
    --space-sm: clamp(0.75rem, 1.5vw, 1rem);
    --space-md: clamp(1rem, 2vw, 1.5rem);
    --space-lg: clamp(1.5rem, 3vw, 2.25rem);
    --space-xl: clamp(2.25rem, 4vw, 3rem);

    /* Glassmorphism variables */
    --glass-bg: rgba(255, 255, 255, 0.1);
    --glass-border: rgba(255, 255, 255, 0.2);
    --glass-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
    --glass-blur: blur(10px);

    /* Transition Speed */
    --transition-speed: 0.3s ease;
}

/* General Styles */
body {
    font-family: var(--font-family-secondary);
    background-color: var(--primary-color-1);
    color: var(--primary-color-2);
    margin: 0;
    padding: 0;
    line-height: 1.6;
    scroll-behavior: smooth;
    scroll-padding-top: var(--space-xl); /* Adjust as needed based on header height */
}

/* Typography */
h1, h2, h3 {
    font-family: var(--font-family-primary);
    font-weight: bold;
    color: var(--primary-color-2);
    line-height: 1.2;
    margin-bottom: var(--space-sm);
}

h1 {
    font-size: clamp(2rem, 5vw, 4rem);
}

h2 {
    font-size: clamp(1.5rem, 4vw, 3rem);
}

h3 {
    font-size: clamp(1.2rem, 3vw, 2rem);
}

p {
    font-size: clamp(0.9rem, 2vw, 1.1rem);
    color: var(--primary-color-2);
    margin-bottom: var(--space-md);
}

a {
    color: var(--primary-color-2);
    text-decoration: none;
    transition: color var(--transition-speed);
}

a:focus {
    outline: none; /* Remove default focus outline */
    color: var(--primary-color-3); /* Change color on focus */
}

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-lg);
}

header, main, footer {
    padding: var(--space-lg) 0;
}

section {
    margin-bottom: var(--space-xl);
}

/* Glassmorphism Effect */
.glass {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow: var(--glass-shadow);
    backdrop-filter: var(--glass-blur);
    border-radius: 12px;
    padding: var(--space-md);
}

/* Header */
.site-header {
    position: sticky;
    top: 0;
    z-index: 100;
}

.site-header .container {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: bold;
}

nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
}

nav ul li {
    margin-left: var(--space-md);
}

nav a {
    display: block;
    padding: var(--space-xs) var(--space-sm);
    border-radius: 8px;
    transition: background-color var(--transition-speed);
}

nav a:hover, nav a:focus {
    background-color: rgba(255, 255, 255, 0.1);
}

/* Hero Section */
.hero {
    position: relative;
    overflow: hidden;
    border-radius: 12px;
}

.hero-image {
    width: 100%;
    height: auto;
    display: block;
}

.hero-content {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    text-align: center;
    width: 90%;
    max-width: 800px;
}

.hero-content h1, .hero-content p {
    color: var(--primary-color-2);
}

/* Buttons */
.btn {
    display: inline-block;
    padding: var(--space-sm) var(--space-md);
    font-size: clamp(0.8rem, 1.5vw, 1rem);
    font-weight: bold;
    text-align: center;
    text-decoration: none;
    border-radius: 8px;
    transition: transform var(--transition-speed), box-shadow var(--transition-speed);
}

.btn:hover {
    transform: translateY(-2px) scale(1.02);
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.4);
}

.btn:focus {
    outline: none;
    box-shadow: 0 0 0 3px var(--primary-color-3); /* Example focus style */
}

.btn-primary {
    background-color: var(--primary-color-2);
    color: var(--primary-color-1);
    border: 2px solid var(--primary-color-2);
}

.btn-secondary {
    background-color: transparent;
    color: var(--primary-color-2);
    border: 2px solid var(--primary-color-2);
}

/* Services Section (Grid Layout) */
.services-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--space-lg);
}

.service-item {
    text-align: center;
    padding: var(--space-md);
    border-radius: 8px;
    transition: transform var(--transition-speed);
}

.service-item:hover {
    transform: translateY(-5px);
}

.service-item img {
    width: 100%;
    height: auto;
    border-radius: 8px;
    margin-bottom: var(--space-sm);
}

/* Footer */
footer {
    text-align: center;
    font-size: 0.8rem;
    color: var(--primary-color-3);
}

/* Animations (Example - Fade In) */
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

.fade-in {
    animation: fadeIn 1s ease-out forwards;
}

/* Responsive Design (Example - Adjust container padding) */
@media (max-width: 768px) {
    .container {
        padding: var(--space-md);
    }

    .hero-content {
        width: 95%;
    }

    h1 {
        font-size: clamp(2rem, 7vw, 3rem);
    }
}

script.js.content:
document.addEventListener('DOMContentLoaded', function() {
    // Smooth scrolling for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();

            const targetId = this.getAttribute('href').substring(1);
            const targetElement = document.getElementById(targetId);

            if (targetElement) {
                const headerHeight = document.querySelector('header').offsetHeight; // Get actual header height
                window.scrollTo({
                    top: targetElement.offsetTop - headerHeight,
                    behavior: 'smooth'
                });
            }
        });
    });

    // Contact Form Validation
    const contactForm = document.getElementById('contactForm');
    if (contactForm) {
        contactForm.addEventListener('submit', function(event) {
            let isValid = true;

            const nameInput = document.getElementById('name');
            const emailInput = document.getElementById('email');
            const messageInput = document.getElementById('message');

            if (!nameInput.value.trim()) {
                alert('Please enter your name.');
                isValid = false;
                nameInput.focus();
            } else if (!emailInput.value.trim()) {
                alert('Please enter your email.');
                isValid = false;
                emailInput.focus();
            } else if (!isValidEmail(emailInput.value.trim())) {
                alert('Please enter a valid email address.');
                isValid = false;
                emailInput.focus();
            } else if (!messageInput.value.trim()) {
                alert('Please enter your message.');
                isValid = false;
                messageInput.focus();
            }


            if (!isValid) {
                event.preventDefault(); // Prevent form submission
            }
        });
    }

    function isValidEmail(email) {
        const emailRegex = /^\w[-\.]+@([\w-]+\.)+[\w-]{2,4}$/g;
        return emailRegex.test(email);
    }

     // Add active class to current page
     const currentPage = window.location.pathname;
     const navLinks = document.querySelectorAll('nav a');

     navLinks.forEach(link => {
         if (link.href.includes(currentPage)) {
             link.classList.add('active');
         }
     });
});

style.css.content:
/* style.css */

/* Root variables for consistent theming */
:root {
    --primary-color: #3498db; /* Example: Blue */
    --secondary-color: #e74c3c; /* Example: Red */
    --background-color: #f0f0f0;
    --text-color: #333;
    --light-gray: #ddd;
    --glass-bg: rgba(255, 255, 255, 0.2);
    --glass-border: rgba(255, 255, 255, 0.3);
    --box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.1);
    --darken-factor: 10%; /* Define the darken factor */
}

/* General body styles */
body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
    background-color: var(--background-color);
    color: var(--text-color);
    margin: 0;
    padding: 0;
    line-height: 1.6;
    overflow-x: hidden; /* Prevent horizontal scroll */
    scroll-behavior: smooth; /* Smooth scrolling */
}

/* Utility classes (similar to Tailwind CSS) */

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
}

.grid {
    display: grid;
    gap: 20px;
}

.grid-2 {
    grid-template-columns: 1fr 1fr;
}

.flex {
    display: flex;
    align-items: center;
}

.justify-between {
    justify-content: space-between;
}

.justify-center {
    justify-content: center;
}

.items-center {
    align-items: center;
}

.text-center {
    text-align: center;
}

/* Typography */
.text-xl {
    font-size: 2rem;
}

.text-lg {
    font-size: 1.5rem;
}

.text-md {
    font-size: 1.2rem;
}

.font-bold {
    font-weight: bold;
}

/* Color */
.text-primary {
    color: var(--primary-color);
}

.bg-primary {
    background-color: var(--primary-color);
    color: white;
}

/* Spacing */
.my-2 {
    margin-top: 0.5rem;
    margin-bottom: 0.5rem;
}

.my-4 {
    margin-top: 1rem;
    margin-bottom: 1rem;
}

.py-2 {
    padding-top: 0.5rem;
    padding-bottom: 0.5rem;
}

.py-4 {
    padding-top: 1rem;
    padding-bottom: 1rem;
}

.px-2 {
    padding-left: 0.5rem;
    padding-right: 0.5rem;
}

.px-4 {
    padding-left: 1rem;
    padding-right: 1rem;
}

/* Glassmorphism card */
.glass-card {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    box-shadow: var(--box-shadow);
    padding: 20px;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    transition: transform 0.3s ease;
}

.glass-card:hover {
    transform: translateY(-5px);
}

/* Navigation */
nav {
    background: var(--glass-bg);
    border-bottom: 1px solid var(--glass-border);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    padding: 10px 20px;
    position: sticky;
    top: 0;
    z-index: 100;
}

nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: center; /* Center the navigation items */
}

nav li {
    margin: 0 15px;
}

nav a {
    color: var(--text-color);
    text-decoration: none;
    font-weight: 500;
    transition: color 0.3s ease;
    padding: 8px 12px; /* Add padding to the links */
    border-radius: 5px; /* Add rounded corners */
}

nav a:hover {
    color: var(--primary-color);
    background-color: rgba(255, 255, 255, 0.1); /* Add a subtle background on hover */
}

/* Active nav link style */
nav a.active {
    color: var(--primary-color);
    font-weight: bold;
}

/* Button styles */
.btn {
    background-color: var(--primary-color);
    color: white;
    padding: 10px 20px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 1rem;
    transition: background-color 0.3s ease;
    text-decoration: none; /* Ensure it doesn't inherit link styles */
    display: inline-block; /* Allows setting padding and margins */
}

.btn:hover {
    background-color: color-mix(var(--darken-factor), var(--primary-color), black);
}

/* Hero section */
.hero {
    padding: 100px 20px;
    text-align: center;
    background: linear-gradient(to right, var(--primary-color), var(--secondary-color));
    color: white;
}

.hero h1 {
    font-size: 3rem;
    margin-bottom: 20px;
}

.hero p {
    font-size: 1.2rem;
    margin-bottom: 30px;
}

/* Image styles */
img {
    max-width: 100%;
    height: auto;
    border-radius: 8px;
    box-shadow: var(--box-shadow);
}

/* Footer styles */
footer {
    text-align: center;
    padding: 20px;
    background-color: var(--light-gray);
    border-top: 1px solid var(--glass-border);
    color: var(--text-color);
}

/* Improve footer contrast */
footer p {
    color: #555;
}

/* Animations */
@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

/* Example usage of animation */
.fade-in {
    animation: fadeIn 1s ease-in-out;
}

/* Media Queries for Responsive Design */

/* Small screens (up to 600px) */
@media (max-width: 600px) {
    .container {
        padding: 10px;
    }

    .grid-2 {
        grid-template-columns: 1fr;
    }

    .text-xl {
        font-size: 1.5rem;
    }

    .hero {
        padding: 50px 10px;
    }

    .hero h1 {
        font-size: 2rem;
    }
    nav ul {
        flex-direction: column;
        align-items: flex-start; /* Align items to the start on small screens */
    }

    nav li {
        margin: 10px 0; /* Add vertical margin between nav items */
    }
}

/* Medium screens (601px to 992px) */
@media (min-width: 601px) and (max-width: 992px) {
    .container {
        padding: 15px;
    }

    .grid-2 {
        grid-template-columns: 1fr; /* Stack on smaller screens */
    }

    .text-xl {
        font-size: 1.75rem;
    }
}

/* Large screens (993px and above) */
@media (min-width: 993px) {
    .container {
        padding: 20px;
    }
}

/* Additional styles */

