document.addEventListener('DOMContentLoaded', () => {
  const loginForm = document.getElementById('loginForm');

  loginForm.addEventListener('submit', async (event) => {
    event.preventDefault();

    const email = document.getElementById('email').value;
    const password = document.getElementById('password').value;

    if (!validateForm(email, password)) {
      return;
    }

    try {
      const response = await simulateLogin(email, password); // Simulate backend call

      if (response.success) {
        // Store token or user data (simulated)
        localStorage.setItem('token', 'fakeToken');
        localStorage.setItem('user', JSON.stringify({ email: email }));

        // Redirect to dashboard or main page
        window.location.href = '/dashboard.html'; // Replace with your actual dashboard URL
      } else {
        displayError(response.message);
      }
    } catch (error) {
      displayError('An unexpected error occurred. Please try again.');
    }
  });

  function validateForm(email, password) {
    clearErrors();

    if (!email) {
      displayError('Email is required.');
      return false;
    }

    if (!password) {
      displayError('Password is required.');
      return false;
    }

    // Basic email validation
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      displayError('Invalid email format.');
      return false;
    }

    return true;
  }

  async function simulateLogin(email, password) {
    // Simulate an API call with a delay
    return new Promise((resolve) => {
      setTimeout(() => {
        if (email === 'test@example.com' && password === 'password') {
          resolve({ success: true, message: 'Login successful' });
        } else {
          resolve({ success: false, message: 'Invalid credentials' });
        }
      }, 1500); // Simulate 1.5 seconds delay
    });
  }

  function displayError(message) {
    const errorContainer = document.getElementById('error-message');
    errorContainer.textContent = message;
    errorContainer.style.display = 'block'; // Make sure it's visible
  }

  function clearErrors() {
    const errorContainer = document.getElementById('error-message');
    errorContainer.textContent = '';
    errorContainer.style.display = 'none';
  }
});

