/* Glassmorphism variables */
:root {
  --glass-bg: rgba(255, 255, 255, 0.2);
  --glass-border: rgba(255, 255, 255, 0.3);
  --glass-blur: 10px;
  --glass-box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.1);
  --primary-color: #3490dc; /* Tailwind's blue-500 */
  --secondary-color: #9561e2; /* Tailwind's purple-500 */
  --text-color-light: #f7fafc; /* Tailwind's gray-100 */
  --text-color-dark: #1a202c; /* Tailwind's gray-900 */
  --success-color: #38c172; /* Tailwind's green-500 */
  --error-color: #e3342f; /* Tailwind's red-500 */
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
