  box-shadow: var(--glass-box-shadow);
  text-align: center;
}

h1 {
  color: var(--text-color-light);
  margin-bottom: 1.5rem;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
}

.form-group {
  margin-bottom: 1.25rem;
