document.addEventListener('DOMContentLoaded', function() {
    // Light/Dark Mode Toggle
    const themeToggle = document.getElementById('theme-toggle');
    if (themeToggle) {
        themeToggle.addEventListener('click', function() {
            document.body.classList.toggle('dark-mode');
            // Store the theme preference in local storage
            if (document.body.classList.contains('dark-mode')) {
                localStorage.setItem('theme', 'dark');
            } else {
                localStorage.setItem('theme', 'light');
            }
        });

        // Check for stored theme preference on page load
        if (localStorage.getItem('theme') === 'dark') {
            document.body.classList.add('dark-mode');
        }
    }

    // Navigation (Basic Example - can be expanded)
    const navLinks = document.querySelectorAll('nav a');
    navLinks.forEach(link => {
        link.addEventListener('click', function(event) {
            // Basic example: Prevent default link behavior and log the link
            event.preventDefault();
            console.log('Navigating to:', this.href);
            // Add more complex navigation logic here, like smooth scrolling
        });
    });

    // Search Functionality (Mock)
    const searchInput = document.getElementById('search-input');
    const searchButton = document.getElementById('search-button');

    if (searchInput && searchButton) {
        searchButton.addEventListener('click', function(event) {
            event.preventDefault();
            const searchTerm = searchInput.value;
            console.log('Searching for:', searchTerm);
            // Implement actual search logic here (e.g., fetching data)
            alert('Search functionality is a mock. Searching for: ' + searchTerm); // Replace with actual search
        });
    }

    // Mock Progress Tracker (Example)
    const progressBar = document.getElementById('progress-bar');
    if (progressBar) {
        let progress = 0;
        const interval = setInterval(function() {
            progress += 10;
            progressBar.value = progress;
            if (progress >= 100) {
                clearInterval(interval);
                alert('Progress complete!');
                progressBar.value = 0; // Reset the bar
                progress = 0;
            }
        }, 500);
    }

    // Code Block Copy Functionality
    const codeBlocks = document.querySelectorAll('pre code');

    codeBlocks.forEach(codeBlock => {
        const copyButton = document.createElement('button');
        copyButton.textContent = 'Copy';
        copyButton.classList.add('copy-button'); // Add a class for styling
        codeBlock.parentNode.insertBefore(copyButton, codeBlock); // Insert button

        copyButton.addEventListener('click', function() {
            const code = codeBlock.textContent;
            navigator.clipboard.writeText(code)
                .then(() => {
                    copyButton.textContent = 'Copied!';
                    setTimeout(() => {
                        copyButton.textContent = 'Copy';
                    }, 2000); // Reset button text
                })
                .catch(err => {
                    console.error('Failed to copy text: ', err);
                    copyButton.textContent = 'Error';
                });
        });
    });
});

