snake-js/js/script.js.content:
// Game Board
const board = document.getElementById('game-board');
const boardSize = 20; // Number of cells in each row/column
board.style.width = boardSize * 20 + 'px'; // Assuming each cell is 20px wide/high
board.style.height = boardSize * 20 + 'px';

// Snake
let snake = [{ x: 10, y: 10 }]; // Initial snake position
let food = generateFood();
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;
let direction = 'right'; // Initial direction
let gameInterval;
let gameSpeed = 150; // milliseconds

// Scoreboard
const scoreElement = document.getElementById('score');
const highScoreElement = document.getElementById('high-score');
highScoreElement.innerText = 'High Score: ' + highScore;

// Functions
function updateScore() {
    scoreElement.innerText = 'Score: ' + score;
}

function generateFood() {
    let newFood;
    while (!newFood || snake.some(segment => segment.x === newFood.x && segment.y === newFood.y)) {
        newFood = {
            x: Math.floor(Math.random() * boardSize),
            y: Math.floor(Math.random() * boardSize)
        };
    }
    return newFood;
}

function draw() {
    board.innerHTML = ''; // Clear the board

    // Draw Snake
    snake.forEach(segment => {
        const snakeElement = document.createElement('div');
        snakeElement.style.gridRowStart = segment.y + 1;
        snakeElement.style.gridColumnStart = segment.x + 1;
        snakeElement.classList.add('snake');
        board.appendChild(snakeElement);
    });

    // Draw Food
    const foodElement = document.createElement('div');
    foodElement.style.gridRowStart = food.y + 1;
    foodElement.style.gridColumnStart = food.x + 1;
    foodElement.classList.add('food');
    board.appendChild(foodElement);
}

function move() {
    const head = { ...snake[0] }; // Copy the head

    switch (direction) {
        case 'up':
            head.y--;
            break;
        case 'down':
            head.y++;
            break;
        case 'left':
            head.x--;
            break;
        case 'right':
            head.x++;
            break;
    }

    // Check for collision with walls
    if (head.x < 0 || head.x >= boardSize || head.y < 0 || head.y >= boardSize) {
        gameOver();
        return;
    }

    // Check for collision with itself
    if (snake.some(segment => segment.x === head.x && segment.y === head.y)) {
        gameOver();
        return;
    }

    snake.unshift(head); // Add new head

    // Check if food was eaten
    if (head.x === food.x && head.y === food.y) {
        score += 10;
        updateScore();
        food = generateFood();

        if (score > highScore) {
            highScore = score;
            localStorage.setItem('highScore', highScore);
            highScoreElement.innerText = 'High Score: ' + highScore;
        }
    } else {
        snake.pop(); // Remove tail if no food eaten
    }
}

function gameOver() {
    clearInterval(gameInterval);
    alert('Game Over! Your score: ' + score);
    snake = [{ x: 10, y: 10 }];
    food = generateFood();
    direction = 'right';
    score = 0;
    updateScore();
    gameSpeed = 150;
    startGame();
}

function changeDirection(e) {
    const key = e.key;

    if ((key === 'ArrowUp' || key === 'w') && direction !== 'down') {
        direction = 'up';
    } else if ((key === 'ArrowDown' || key === 's') && direction !== 'up') {
        direction = 'down';
    } else if ((key === 'ArrowLeft' || key === 'a') && direction !== 'right') {
        direction = 'left';
    } else if ((key === 'ArrowRight' || key === 'd') && direction !== 'left') {
        direction = 'right';
    }
}

function startGame() {
    clearInterval(gameInterval);
    gameInterval = setInterval(() => {
        move();
        draw();
    }, gameSpeed);
}

// Event Listeners
document.addEventListener('keydown', changeDirection);

// Initialize game
updateScore();
startGame();

