const gameBoard = document.getElementById('game-board');
const scoreDisplay = document.getElementById('score');

// Initialize game
function init() {
  gameInterval = setInterval(update, gameSpeed);
  document.addEventListener('keydown', handleInput);
  updateScore();
}

// Update game state
function update() {
  moveSnake();
  if (checkCollision()) {
    gameOver();
    return;
  }
  if (eatFood()) {
    growSnake();
    food = generateFood();
    updateScore();
    increaseSpeed();
  }
  render();
}

// Render game
function render() {
  gameBoard.innerHTML = ''; // Clear the board
  drawSnake();
  drawFood();
}

// Snake functions
function drawSnake() {
  snake.forEach(segment => {
    const snakeElement = document.createElement('div');
    snakeElement.style.gridRowStart = segment.y;
    snakeElement.style.gridColumnStart = segment.x;
    snakeElement.classList.add('snake');
    gameBoard.appendChild(snakeElement);
  });
}

function moveSnake() {
  const head = { ...snake[0] }; // Copy the head

  switch (direction) {
    case 'up':
      head.y--;
      break;
    case 'down':
      head.y++;
      break;
    case 'left':
      head.x--;
      break;
    case 'right':
      head.x++;
      break;
  }

  snake.unshift(head); // Add new head
  snake.pop(); // Remove tail
}


function growSnake() {
    const tail = { ...snake[snake.length - 1] }; // Copy the tail
    snake.push(tail); // Add the tail back, effectively growing the snake
}


// Food functions
function drawFood() {
  const foodElement = document.createElement('div');
  foodElement.style.gridRowStart = food.y;
  foodElement.style.gridColumnStart = food.x;
  foodElement.classList.add('food');
  gameBoard.appendChild(foodElement);
}

function generateFood() {
  let newFood;
  while (newFood === undefined || isFoodOnSnake(newFood)) {
    newFood = {
      x: Math.floor(Math.random() * gridSize) + 1,
      y: Math.floor(Math.random() * gridSize) + 1
    };
  }
  return newFood;
}

function isFoodOnSnake(food) {
  return snake.some(segment => segment.x === food.x && segment.y === food.y);
}

function eatFood() {
  return snake[0].x === food.x && snake[0].y === food.y;
}

// Input handling
function handleInput(event) {
  switch (event.key) {
    case 'ArrowUp':
      if (direction !== 'down') direction = 'up';
      break;
    case 'ArrowDown':
      if (direction !== 'up') direction = 'down';
      break;
    case 'ArrowLeft':
      if (direction !== 'right') direction = 'left';
      break;
    case 'ArrowRight':
      if (direction !== 'left') direction = 'right';
      break;
  }
}

// Collision detection
function checkCollision() {
  const head = snake[0];
  if (head.x < 1 || head.x > gridSize || head.y < 1 || head.y > gridSize) {
    return true; // Border collision
  }

  for (let i = 1; i < snake.length; i++) {
    if (head.x === snake[i].x && head.y === snake[i].y) {
      return true; // Self collision
    }
  }

  return false;
}

// Game over
function gameOver() {
  clearInterval(gameInterval);
  alert(`Game Over! Your score was ${score}`);
  resetGame();
}

// Score update
function updateScore() {
  score = snake.length - 1;
  scoreDisplay.textContent = `Score: ${score}`;
}

// Speed increase
function increaseSpeed() {
  if (gameSpeed > 20) {
    gameSpeed -= 5;
    clearInterval(gameInterval);
    gameInterval = setInterval(update, gameSpeed);
  }
}

// Reset game
function resetGame() {
  snake = [{ x: 10, y: 10 }];
  food = generateFood();
  direction = 'right';
  gameSpeed = 100;
  score = 0;
  clearInterval(gameInterval);
  gameInterval = setInterval(update, gameSpeed);
  updateScore();
}

// Start the game
init();

