// script.js

const API_BASE_URL = 'http://localhost:3000/api'; // Adjust as needed

// Utility function for making API calls
async function apiCall(url, method = 'GET', body = null, requiresAuth = false) {
  const headers = {
    'Content-Type': 'application/json',
  };

  if (requiresAuth) {
    const token = localStorage.getItem('token');
    if (!token) {
      window.location.href = '/login.html'; // Redirect to login if no token
      throw new Error('Unauthorized: No token found.');
    }
    headers['Authorization'] = `Bearer ${token}`;
  }

  const options = {
    method,
    headers,
  };

  if (body) {
    options.body = JSON.stringify(body);
  }

  try {
    const response = await fetch(API_BASE_URL + url, options);

    if (!response.ok) {
      if (response.status === 401) {
        // Handle unauthorized access (e.g., redirect to login)
        localStorage.removeItem('token');
        window.location.href = '/login.html';
        throw new Error('Unauthorized');
      }
      throw new Error(`HTTP error! Status: ${response.status}`);
    }

    const data = await response.json();
    return data;
  } catch (error) {
    console.error('API call failed:', error);
    throw error; // Re-throw the error to be handled by the caller
  }
}


// --- Product Handling ---
async function fetchProducts() {
  try {
    const products = await apiCall('/products');
    return products;
  } catch (error) {
    console.error('Failed to fetch products:', error);
    return [];
  }
}


// --- Cart Handling ---
async function addToCart(productId, quantity = 1) {
  try {
    const cart = await apiCall('/cart/add', 'POST', { productId, quantity }, true);
    updateCartDisplay(cart);
    return cart;
  } catch (error) {
    console.error('Failed to add to cart:', error);
  }
}

async function getCart() {
    try {
      const cart = await apiCall('/cart', 'GET', null, true);
      return cart;
    } catch (error) {
      console.error('Failed to get cart:', error);
      return null;
    }
  }


async function updateCartItem(productId, quantity) {
  try {
    const cart = await apiCall('/cart/update', 'PUT', { productId, quantity }, true);
    updateCartDisplay(cart);
    return cart;
  } catch (error) {
    console.error('Failed to update cart item:', error);
  }
}

async function removeFromCart(productId) {
  try {
    const cart = await apiCall('/cart/remove', 'DELETE', { productId }, true);
    updateCartDisplay(cart);
    return cart;
  } catch (error) {
    console.error('Failed to remove from cart:', error);
  }
}


function updateCartDisplay(cart) {
  // Implement logic to update the cart display in the UI
  // This might involve updating the cart icon badge,
  // refreshing the cart items in the cart page, etc.
  console.log('Cart updated:', cart);

  // Example update of cart count in a hypothetical element with id "cart-count"
  const cartCountElement = document.getElementById('cart-count');
  if (cartCountElement) {
    let totalQuantity = 0;
    if (cart && cart.items) {
      cart.items.forEach(item => {
        totalQuantity += item.quantity;
      });
    }
    cartCountElement.textContent = totalQuantity;
  }

  // Example update of cart items in a hypothetical element with id "cart-items" (for cart.html)
  const cartItemsElement = document.getElementById('cart-items');
  if (cartItemsElement) {
    cartItemsElement.innerHTML = ''; // Clear existing items
    if (cart && cart.items) {
      cart.items.forEach(item => {
        const listItem = document.createElement('li');
        listItem.textContent = `${item.product.name} x ${item.quantity} - $${item.product.price * item.quantity}`;
        cartItemsElement.appendChild(listItem);
      });
    } else {
      cartItemsElement.textContent = 'Your cart is empty.';
    }
  }

  // Example update of cart total in a hypothetical element with id "cart-total" (for cart.html)
  const cartTotalElement = document.getElementById('cart-total');
  if (cartTotalElement) {
    let totalPrice = 0;
    if (cart && cart.items) {
      cart.items.forEach(item => {
        totalPrice += item.product.price * item.quantity;
      });
    }
    cartTotalElement.textContent = `Total: $${totalPrice}`;
  }
}



// --- User Authentication ---
async function registerUser(userData) {
  try {
    const response = await apiCall('/auth/register', 'POST', userData);
    localStorage.setItem('token', response.token);
    return response;
  } catch (error) {
    console.error('Registration failed:', error);
    throw error;
  }
}

async function loginUser(userData) {
  try {
    const response = await apiCall('/auth/login', 'POST', userData);
    localStorage.setItem('token', response.token);
    return response;
  } catch (error) {
    console.error('Login failed:', error);
    throw error;
  }
}

function logoutUser() {
  localStorage.removeItem('token');
  window.location.href = '/login.html';
}

function isLoggedIn() {
  return !!localStorage.getItem('token');
}

// --- Checkout ---
async function checkout() {
  try {
    const order = await apiCall('/checkout', 'POST', null, true);
    // Handle successful checkout (e.g., redirect to order confirmation page)
    console.log('Checkout successful:', order);
    return order;
  } catch (error) {
    console.error('Checkout failed:', error);
    throw error;
  }
}


// --- Event Listeners and Initialization ---

// Example: Add event listener to a hypothetical "add to cart" button
// Ensure this code runs *after* the DOM is loaded and the button exists

// Example: Fetch cart on page load if user is logged in
document.addEventListener('DOMContentLoaded', async () => {
  if (isLoggedIn()) {
    try {
      const cart = await getCart();
      updateCartDisplay(cart);
    } catch (error) {
      console.error('Failed to fetch cart on page load:', error);
    }
  }
});


// Make functions available globally (optional, but useful for inline event handlers in HTML)
window.addToCart = addToCart;
window.updateCartItem = updateCartItem;
window.removeFromCart = removeFromCart;
window.logoutUser = logoutUser;
window.checkout = checkout;
window.fetchProducts = fetchProducts;
window.getCart = getCart;

